window.KH_SURA(34, {"sura": "سبأ", "n": 34, "ayat": {"1": "الْحَمْدُ لِلَّهِ الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَلَهُ الْحَمْدُ فِي الْآخِرَةِ وَهُوَ الْحَكِيمُ الْخَبِيرُ", "2": "يَعْلَمُ مَا يَلِجُ فِي الْأَرْضِ وَمَا يَخْرُجُ مِنْهَا وَمَا يَنْزِلُ مِنَ السَّمَاءِ وَمَا يَعْرُجُ فِيهَا وَهُوَ الرَّحِيمُ الْغَفُورُ", "3": "وَقَالَ الَّذِينَ كَفَرُوا لَا تَأْتِينَا السَّاعَةُ قُلْ بَلَى وَرَبِّي لَتَأْتِيَنَّكُمْ عَالِمِ الْغَيْبِ لَا يَعْزُبُ عَنْهُ مِثْقَالُ ذَرَّةٍ فِي السَّمَاوَاتِ وَلَا فِي الْأَرْضِ وَلَا أَصْغَرُ مِنْ ذَلِكَ وَلَا أَكْبَرُ إِلَّا فِي كِتَابٍ مُبِينٍ", "4": "لِيَجْزِيَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ أُولَئِكَ لَهُمْ مَغْفِرَةٌ وَرِزْقٌ كَرِيمٌ", "5": "وَالَّذِينَ سَعَوْا فِي آيَاتِنَا مُعَاجِزِينَ أُولَئِكَ لَهُمْ عَذَابٌ مِنْ رِجْزٍ أَلِيمٌ", "6": "وَيَرَى الَّذِينَ أُوتُوا الْعِلْمَ الَّذِي أُنْزِلَ إِلَيْكَ مِنْ رَبِّكَ هُوَ الْحَقَّ وَيَهْدِي إِلَى صِرَاطِ الْعَزِيزِ الْحَمِيدِ", "7": "وَقَالَ الَّذِينَ كَفَرُوا هَلْ نَدُلُّكُمْ عَلَى رَجُلٍ يُنَبِّئُكُمْ إِذَا مُزِّقْتُمْ كُلَّ مُمَزَّقٍ إِنَّكُمْ لَفِي خَلْقٍ جَدِيدٍ", "8": "أَفْتَرَى عَلَى اللَّهِ كَذِبًا أَمْ بِهِ جِنَّةٌ بَلِ الَّذِينَ لَا يُؤْمِنُونَ بِالْآخِرَةِ فِي الْعَذَابِ وَالضَّلَالِ الْبَعِيدِ", "9": "أَفَلَمْ يَرَوْا إِلَى مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ مِنَ السَّمَاءِ وَالْأَرْضِ إِنْ نَشَأْ نَخْسِفْ بِهِمُ الْأَرْضَ أَوْ نُسْقِطْ عَلَيْهِمْ كِسَفًا مِنَ السَّمَاءِ إِنَّ فِي ذَلِكَ لَآيَةً لِكُلِّ عَبْدٍ مُنِيبٍ", "10": "وَلَقَدْ آتَيْنَا دَاوُودَ مِنَّا فَضْلًا يَاجِبَالُ أَوِّبِي مَعَهُ وَالطَّيْرَ وَأَلَنَّا لَهُ الْحَدِيدَ", "11": "أَنِ اعْمَلْ سَابِغَاتٍ وَقَدِّرْ فِي السَّرْدِ وَاعْمَلُوا صَالِحًا إِنِّي بِمَا تَعْمَلُونَ بَصِيرٌ", "12": "وَلِسُلَيْمَانَ الرِّيحَ غُدُوُّهَا شَهْرٌ وَرَوَاحُهَا شَهْرٌ وَأَسَلْنَا لَهُ عَيْنَ الْقِطْرِ وَمِنَ الْجِنِّ مَنْ يَعْمَلُ بَيْنَ يَدَيْهِ بِإِذْنِ رَبِّهِ وَمَنْ يَزِغْ مِنْهُمْ عَنْ أَمْرِنَا نُذِقْهُ مِنْ عَذَابِ السَّعِيرِ", "13": "يَعْمَلُونَ لَهُ مَا يَشَاءُ مِنْ مَحَارِيبَ وَتَمَاثِيلَ وَجِفَانٍ كَالْجَوَابِ وَقُدُورٍ رَاسِيَاتٍ اعْمَلُوا آلَ دَاوُودَ شُكْرًا وَقَلِيلٌ مِنْ عِبَادِيَ الشَّكُورُ", "14": "فَلَمَّا قَضَيْنَا عَلَيْهِ الْمَوْتَ مَا دَلَّهُمْ عَلَى مَوْتِهِ إِلَّا دَابَّةُ الْأَرْضِ تَأْكُلُ مِنْسَأَتَهُ فَلَمَّا خَرَّ تَبَيَّنَتِ الْجِنُّ أَنْ لَوْ كَانُوا يَعْلَمُونَ الْغَيْبَ مَا لَبِثُوا فِي الْعَذَابِ الْمُهِينِ", "15": "لَقَدْ كَانَ لِسَبَإٍ فِي مَسْكَنِهِمْ آيَةٌ جَنَّتَانِ عَنْ يَمِينٍ وَشِمَالٍ كُلُوا مِنْ رِزْقِ رَبِّكُمْ وَاشْكُرُوا لَهُ بَلْدَةٌ طَيِّبَةٌ وَرَبٌّ غَفُورٌ", "16": "فَأَعْرَضُوا فَأَرْسَلْنَا عَلَيْهِمْ سَيْلَ الْعَرِمِ وَبَدَّلْنَاهُمْ بِجَنَّتَيْهِمْ جَنَّتَيْنِ ذَوَاتَيْ أُكُلٍ خَمْطٍ وَأَثْلٍ وَشَيْءٍ مِنْ سِدْرٍ قَلِيلٍ", "17": "ذَلِكَ جَزَيْنَاهُمْ بِمَا كَفَرُوا وَهَلْ نُجَازِي إِلَّا الْكَفُورَ", "18": "وَجَعَلْنَا بَيْنَهُمْ وَبَيْنَ الْقُرَى الَّتِي بَارَكْنَا فِيهَا قُرًى ظَاهِرَةً وَقَدَّرْنَا فِيهَا السَّيْرَ سِيرُوا فِيهَا لَيَالِيَ وَأَيَّامًا آمِنِينَ", "19": "فَقَالُوا رَبَّنَا بَاعِدْ بَيْنَ أَسْفَارِنَا وَظَلَمُوا أَنْفُسَهُمْ فَجَعَلْنَاهُمْ أَحَادِيثَ وَمَزَّقْنَاهُمْ كُلَّ مُمَزَّقٍ إِنَّ فِي ذَلِكَ لَآيَاتٍ لِكُلِّ صَبَّارٍ شَكُورٍ", "20": "وَلَقَدْ صَدَّقَ عَلَيْهِمْ إِبْلِيسُ ظَنَّهُ فَاتَّبَعُوهُ إِلَّا فَرِيقًا مِنَ الْمُؤْمِنِينَ", "21": "وَمَا كَانَ لَهُ عَلَيْهِمْ مِنْ سُلْطَانٍ إِلَّا لِنَعْلَمَ مَنْ يُؤْمِنُ بِالْآخِرَةِ مِمَّنْ هُوَ مِنْهَا فِي شَكٍّ وَرَبُّكَ عَلَى كُلِّ شَيْءٍ حَفِيظٌ", "22": "قُلِ ادْعُوا الَّذِينَ زَعَمْتُمْ مِنْ دُونِ اللَّهِ لَا يَمْلِكُونَ مِثْقَالَ ذَرَّةٍ فِي السَّمَاوَاتِ وَلَا فِي الْأَرْضِ وَمَا لَهُمْ فِيهِمَا مِنْ شِرْكٍ وَمَا لَهُ مِنْهُمْ مِنْ ظَهِيرٍ", "23": "وَلَا تَنْفَعُ الشَّفَاعَةُ عِنْدَهُ إِلَّا لِمَنْ أَذِنَ لَهُ حَتَّى إِذَا فُزِّعَ عَنْ قُلُوبِهِمْ قَالُوا مَاذَا قَالَ رَبُّكُمْ قَالُوا الْحَقَّ وَهُوَ الْعَلِيُّ الْكَبِيرُ", "24": "قُلْ مَنْ يَرْزُقُكُمْ مِنَ السَّمَاوَاتِ وَالْأَرْضِ قُلِ اللَّهُ وَإِنَّا أَوْ إِيَّاكُمْ لَعَلَى هُدًى أَوْ فِي ضَلَالٍ مُبِينٍ", "25": "قُلْ لَا تُسْأَلُونَ عَمَّا أَجْرَمْنَا وَلَا نُسْأَلُ عَمَّا تَعْمَلُونَ", "26": "قُلْ يَجْمَعُ بَيْنَنَا رَبُّنَا ثُمَّ يَفْتَحُ بَيْنَنَا بِالْحَقِّ وَهُوَ الْفَتَّاحُ الْعَلِيمُ", "27": "قُلْ أَرُونِيَ الَّذِينَ أَلْحَقْتُمْ بِهِ شُرَكَاءَ كَلَّا بَلْ هُوَ اللَّهُ الْعَزِيزُ الْحَكِيمُ", "28": "وَمَا أَرْسَلْنَاكَ إِلَّا كَافَّةً لِلنَّاسِ بَشِيرًا وَنَذِيرًا وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ", "29": "وَيَقُولُونَ مَتَى هَذَا الْوَعْدُ إِنْ كُنْتُمْ صَادِقِينَ", "30": "قُلْ لَكُمْ مِيعَادُ يَوْمٍ لَا تَسْتَأْخِرُونَ عَنْهُ سَاعَةً وَلَا تَسْتَقْدِمُونَ", "31": "وَقَالَ الَّذِينَ كَفَرُوا لَنْ نُؤْمِنَ بِهَذَا الْقُرْآنِ وَلَا بِالَّذِي بَيْنَ يَدَيْهِ وَلَوْ تَرَى إِذِ الظَّالِمُونَ مَوْقُوفُونَ عِنْدَ رَبِّهِمْ يَرْجِعُ بَعْضُهُمْ إِلَى بَعْضٍ الْقَوْلَ يَقُولُ الَّذِينَ اسْتُضْعِفُوا لِلَّذِينَ اسْتَكْبَرُوا لَوْلَا أَنْتُمْ لَكُنَّا مُؤْمِنِينَ", "32": "قَالَ الَّذِينَ اسْتَكْبَرُوا لِلَّذِينَ اسْتُضْعِفُوا أَنَحْنُ صَدَدْنَاكُمْ عَنِ الْهُدَى بَعْدَ إِذْ جَاءَكُمْ بَلْ كُنْتُمْ مُجْرِمِينَ", "33": "وَقَالَ الَّذِينَ اسْتُضْعِفُوا لِلَّذِينَ اسْتَكْبَرُوا بَلْ مَكْرُ اللَّيْلِ وَالنَّهَارِ إِذْ تَأْمُرُونَنَا أَنْ نَكْفُرَ بِاللَّهِ وَنَجْعَلَ لَهُ أَنْدَادًا وَأَسَرُّوا النَّدَامَةَ لَمَّا رَأَوُا الْعَذَابَ وَجَعَلْنَا الْأَغْلَالَ فِي أَعْنَاقِ الَّذِينَ كَفَرُوا هَلْ يُجْزَوْنَ إِلَّا مَا كَانُوا يَعْمَلُونَ", "34": "وَمَا أَرْسَلْنَا فِي قَرْيَةٍ مِنْ نَذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا بِمَا أُرْسِلْتُمْ بِهِ كَافِرُونَ", "35": "وَقَالُوا نَحْنُ أَكْثَرُ أَمْوَالًا وَأَوْلَادًا وَمَا نَحْنُ بِمُعَذَّبِينَ", "36": "قُلْ إِنَّ رَبِّي يَبْسُطُ الرِّزْقَ لِمَنْ يَشَاءُ وَيَقْدِرُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ", "37": "وَمَا أَمْوَالُكُمْ وَلَا أَوْلَادُكُمْ بِالَّتِي تُقَرِّبُكُمْ عِنْدَنَا زُلْفَى إِلَّا مَنْ آمَنَ وَعَمِلَ صَالِحًا فَأُولَئِكَ لَهُمْ جَزَاءُ الضِّعْفِ بِمَا عَمِلُوا وَهُمْ فِي الْغُرُفَاتِ آمِنُونَ", "38": "وَالَّذِينَ يَسْعَوْنَ فِي آيَاتِنَا مُعَاجِزِينَ أُولَئِكَ فِي الْعَذَابِ مُحْضَرُونَ", "39": "قُلْ إِنَّ رَبِّي يَبْسُطُ الرِّزْقَ لِمَنْ يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ لَهُ وَمَا أَنْفَقْتُمْ مِنْ شَيْءٍ فَهُوَ يُخْلِفُهُ وَهُوَ خَيْرُ الرَّازِقِينَ", "40": "وَيَوْمَ يَحْشُرُهُمْ جَمِيعًا ثُمَّ يَقُولُ لِلْمَلَائِكَةِ أَهَؤُلَاءِ إِيَّاكُمْ كَانُوا يَعْبُدُونَ", "41": "قَالُوا سُبْحَانَكَ أَنْتَ وَلِيُّنَا مِنْ دُونِهِمْ بَلْ كَانُوا يَعْبُدُونَ الْجِنَّ أَكْثَرُهُمْ بِهِمْ مُؤْمِنُونَ", "42": "فَالْيَوْمَ لَا يَمْلِكُ بَعْضُكُمْ لِبَعْضٍ نَفْعًا وَلَا ضَرًّا وَنَقُولُ لِلَّذِينَ ظَلَمُوا ذُوقُوا عَذَابَ النَّارِ الَّتِي كُنْتُمْ بِهَا تُكَذِّبُونَ", "43": "وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالُوا مَا هَذَا إِلَّا رَجُلٌ يُرِيدُ أَنْ يَصُدَّكُمْ عَمَّا كَانَ يَعْبُدُ آبَاؤُكُمْ وَقَالُوا مَا هَذَا إِلَّا إِفْكٌ مُفْتَرًى وَقَالَ الَّذِينَ كَفَرُوا لِلْحَقِّ لَمَّا جَاءَهُمْ إِنْ هَذَا إِلَّا سِحْرٌ مُبِينٌ", "44": "وَمَا آتَيْنَاهُمْ مِنْ كُتُبٍ يَدْرُسُونَهَا وَمَا أَرْسَلْنَا إِلَيْهِمْ قَبْلَكَ مِنْ نَذِيرٍ", "45": "وَكَذَّبَ الَّذِينَ مِنْ قَبْلِهِمْ وَمَا بَلَغُوا مِعْشَارَ مَا آتَيْنَاهُمْ فَكَذَّبُوا رُسُلِي فَكَيْفَ كَانَ نَكِيرِ", "46": "قُلْ إِنَّمَا أَعِظُكُمْ بِوَاحِدَةٍ أَنْ تَقُومُوا لِلَّهِ مَثْنَى وَفُرَادَى ثُمَّ تَتَفَكَّرُوا مَا بِصَاحِبِكُمْ مِنْ جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ لَكُمْ بَيْنَ يَدَيْ عَذَابٍ شَدِيدٍ", "47": "قُلْ مَا سَأَلْتُكُمْ مِنْ أَجْرٍ فَهُوَ لَكُمْ إِنْ أَجْرِيَ إِلَّا عَلَى اللَّهِ وَهُوَ عَلَى كُلِّ شَيْءٍ شَهِيدٌ", "48": "قُلْ إِنَّ رَبِّي يَقْذِفُ بِالْحَقِّ عَلَّامُ الْغُيُوبِ", "49": "قُلْ جَاءَ الْحَقُّ وَمَا يُبْدِئُ الْبَاطِلُ وَمَا يُعِيدُ", "50": "قُلْ إِنْ ضَلَلْتُ فَإِنَّمَا أَضِلُّ عَلَى نَفْسِي وَإِنِ اهْتَدَيْتُ فَبِمَا يُوحِي إِلَيَّ رَبِّي إِنَّهُ سَمِيعٌ قَرِيبٌ", "51": "وَلَوْ تَرَى إِذْ فَزِعُوا فَلَا فَوْتَ وَأُخِذُوا مِنْ مَكَانٍ قَرِيبٍ", "52": "وَقَالُوا آمَنَّا بِهِ وَأَنَّى لَهُمُ التَّنَاوُشُ مِنْ مَكَانٍ بَعِيدٍ", "53": "وَقَدْ كَفَرُوا بِهِ مِنْ قَبْلُ وَيَقْذِفُونَ بِالْغَيْبِ مِنْ مَكَانٍ بَعِيدٍ", "54": "وَحِيلَ بَيْنَهُمْ وَبَيْنَ مَا يَشْتَهُونَ كَمَا فُعِلَ بِأَشْيَاعِهِمْ مِنْ قَبْلُ إِنَّهُمْ كَانُوا فِي شَكٍّ مُرِيبٍ"}, "units": [{"aya": 0, "title": "قوله تعالى: {ويرى الذين أوتوا العلم الذي أنزل إليك من ربك هو الحق} الآية [سبأ: 6]", "mawsua": {"taliq": 5286, "masala": "قوله تعالى: {ويرى الذين أوتوا العلم الذي أنزل إليك من ربك هو الحق} الآية [سبأ: 6]", "sigha": "حكاية خلاف", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "هي مكية، والمراد: المؤمنون بالنبي صلى الله عليه وسلم", "ashab": "", "athar": []}, {"n": 2, "t": "هي مدنية، والمراد: من أسلم بالمدينة من أهل الكتاب؛ كابن سلام وأشباهه", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5286, "mi": 0, "aya": 0, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 155", "qawl": "", "nass": "هي مكية، واختلف في قوله تعالى: {ويرى الذين أوتوا العلم الذي أنزل إليك من ربك هو الحق} الآية [سبأ: 6]، فقالت فرقة: هي مكية، والمراد: المؤمنون بالنبي صلى الله عليه وسلم. وقالت فرقة: هي مدنية، والمراد: من أسلم بالمدينة من أهل الكتاب؛ كابن سلام وأشباهه", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 11, "title": "في السرد", "tabari": {"page": "19/223", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "السرد: هو مسمار حلق الدرع", "taqdim": 0, "n_athar": 1, "qailun": [["قتادة", "تابعي"]], "athar": [63110, 63111, 63119, 63120, 63121]}, {"n": 2, "t": "بل هو الحلق بعينها", "taqdim": 0, "n_athar": 1, "qailun": [["ابن زيد", "تابع التابعين"]], "athar": [63113, 63123]}, {"n": 3, "t": "يقال: درع مسرودة. إذا كانت مسمورة الحلق، واستشهد لقيله ذلك بقول الشاعر :", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 4, "t": "إن الله ﷿ إنما قال لداود: ﴿وقدر في السرد﴾. لأنها كانت قبل ذلك صفائح", "taqdim": 0, "n_athar": 5, "qailun": [["قتادة", "تابعي"], ["ابن عباس", "صحابي"], ["مجاهد", "تابعي"], ["الحكم", "تابعي"]], "athar": [63110, 63111, 63114, 63115, 63116, 63117, 63118, 63119, 63120, 63121]}]}, "mawaqif": [{"taliq": 5296, "mi": 1, "aya": 11, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "19/ 224 - 226", "qawl": "الأول", "nass": "وعنى بقوله: {وقدر في السرد}", "qawaid": ["أقوال السلف"], "tabi": ""}], "mushid": {"i": 1, "imgs": ["034_001_1.png"], "pages": [424], "n": 3, "rajih": [], "daif": [], "match": false}, "mawsua": {"taliq": 5296, "masala": "تفسير قوله: {وقدر في السرد}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أن السرد: هو مسمار حلق الدرع", "ashab": "", "athar": []}, {"n": 2, "t": "أنه الحلق بعينها", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["أقوال السلف"]}, "rulesD": {}}}, {"aya": 15, "title": "السبب الذي من أجله سموا بهذا", "mawsua": {"taliq": 5311, "masala": "السبب الذي من أجله سموا بهذا", "sigha": "خلاف مصرَّح به", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أنه نسبة إلى رجل كان أبا للقبيل كلهم. كما في جاء في قول مقاتل وغيره", "ashab": "", "athar": []}, {"n": 2, "t": "أن سبأ اسم موضع، سمي به القبيل. كما أشار إلى ذلك قول يحيى بن سلام", "ashab": "", "athar": []}, {"n": 3, "t": "أن سبأ اسم لامرأة كانت أم القبيل", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5311, "mi": 0, "aya": 15, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 172 - 173", "qawl": "", "nass": "سبأ", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 16, "title": "تأويل: ﴿فأرسلنا عليهم سيل العرم﴾", "tabari": {"page": "19/251", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿فأرسلنا عليهم سيل العرم﴾. يقول تعالى ذكره: فثقبنا عليهم حين أعرضوا عن تصديق رسلنا سدهم الذي كان يحبس عنهم السيول.", "taqdim": 1, "n_athar": 3, "qailun": [["أبي ميسرة", ""], ["مجاهد", "تابعي"]], "athar": [63290, 63302, 63303, 63311]}, {"n": 2, "t": "إن العرم اسم واد كان لهؤلاء القوم", "taqdim": 0, "n_athar": 3, "qailun": [["ابن عباس", "صحابي"], ["قتادة", "تابعي"]], "athar": [63284, 63286, 63287, 63295, 63299, 63300, 63309, 63310, 63318, 63326, 63330]}, {"n": 3, "t": "العرم: صفة للمسناة التي كانت لهم وليس باسم لها", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [63286, 63287, 63299, 63300, 63309, 63310, 63326]}]}, "mawaqif": [], "mushid": {"i": 2, "imgs": ["034_002_1.png"], "pages": [424], "n": 2, "rajih": [], "daif": [], "match": false}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 16, "title": "في صفة ما حدث عن ذلك النقب مما كان به خراب جنتيهم", "tabari": {"page": "19/252", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "كان صفة ذلك أن السيل لما وجد عملا في السد عمل فيه فخربه ، ثم فاض الماء على جناتهم فغرقها وخرب أرضهم وديارهم", "taqdim": 0, "n_athar": 4, "qailun": [["وهب بن منبه اليماني", "تابعي"], ["قتادة", "تابعي"], ["ابن زيد", "تابع التابعين"]], "athar": [63284, 63295, 63298, 63318, 63322, 63330]}, {"n": 2, "t": "كانت صفة ذلك أن الماء الذي كانوا يعمرون به جناتهم سال إلى موضع غير الموضع الذي كانوا ينتفعون به، فبذلك خربت جناتهم", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [63286, 63287, 63299, 63300, 63309, 63310, 63326]}]}, "mawaqif": [{"taliq": 5314, "mi": 1, "aya": 16, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "19/ 254", "qawl": "الأول", "nass": "والقول الأول أشبه بما دل عليه ظاهر التنزيل، وذلك أن الله -تعالى ذكره- أخبر أنه أرسل عليهم سيل العرم، ولا يكون إرسال ذلك عليهم إلا بإسالته عليهم، أو على جناتهم وأرضهم، لا بصرفه عنهم", "qawaid": ["ظاهر الآية ولفظها"], "tabi": ""}], "mushid": {"i": 3, "imgs": ["034_003_1.png"], "pages": [424], "n": 2, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 5314, "masala": "صفة ما حدث عن ذلك الثقب مما كان فيه خراب جنتيهم", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أن السيل لما وجد عملا في السد عمل فيه، ثم فاض الماء على جناتهم، فغرقها، وخرب أرضهم وديارهم", "ashab": "", "athar": []}, {"n": 2, "t": "أن الماء الذي كانوا يعمرون به جناتهم سال إلى موضع غير الموضع الذي كانوا ينتفعون به، فبذلك خربت جناتهم", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["ظاهر الآية ولفظها"]}, "rulesD": {}}}, {"aya": 18, "title": "معنى {ظاهرة}", "mawsua": {"taliq": 5322, "masala": "معنى {ظاهرة}", "sigha": "حكاية خلاف", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "معناه: مستعلية مرتفعة في الآكام والظراب، وهي أشرف القرى", "ashab": "", "athar": []}, {"n": 2, "t": "معناه: يظهر بعضها من بعض، فهي أبدا في قبضة عين المسافر، ولا يخلو من رؤية شيء منها، فهي ظاهرة بهذا الوجه", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5322, "mi": 0, "aya": 18, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "19/ 261 - 263", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 5322, "mi": 0, "aya": 18, "alam": "ابن عطية", "fil": "حكى", "kind": "نقل", "ref": "7/ 178 - 179", "qawl": "", "nass": "واختلف في معنى {ظاهرة}، فقالت فرقة: معناه: مستعلية مرتفعة في الآكام والظراب، وهي أشرف القرى. وقالت فرقة: معناه: يظهر بعضها من بعض، فهي أبدا في قبضة عين المسافر، ولا يخلو من رؤية شيء منها، فهي ظاهرة بهذا الوجه", "qawaid": ["اللغة"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 23, "title": "في الموصوفين بهذه الصفة", "tabari": {"page": "19/275", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك بالصواب [وأشبهها بظاهر التنزيل] ، القول الذي ذكره الشعبي، عن ابن مسعود؛ لصحة الخبر الذي ذكرناه عن ابن عباس، عن رسول الله ﷺ بتأييده.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "الذين فزع عن قلوبهم الملائكة. قالوا: وإنما يفزع عن قلوبهم من غشية تصيبهم عند سماعهم كلام الله بالوحي", "taqdim": 0, "n_athar": 13, "qailun": [["الشعبى", "تابعي"], ["مسروق", "تابعي"], ["ابن مسعود", "صحابي"], ["سعيد", "تابعي"], ["عبد الله بن مسعود", "صحابي"], ["عروة", "تابعي"], ["النواس بن سمعان", ""], ["ابن عباس", "صحابي"], ["عبد الله بن القاسم", "تابعي"], ["عبد الله", "صحابي"]], "athar": [63434, 63435, 63437, 63438, 63439, 63440, 63457, 63459, 63460, 63462, 63463, 63464, 63465, 63466, 63467, 63468, 63469, 63470, 63472, 63473, 63474, 63475, 63477, 63478]}, {"n": 2, "t": "الموصوفون بذلك الملائكة: إنما يفزع عن قلوبهم فزعهم من قضاء الله الذي يقضيه؛ حذرا أن يكون ذلك قيام الساعة", "taqdim": 0, "n_athar": 1, "qailun": [["قتادة", "تابعي"]], "athar": [63450, 63451, 63479, 63480]}, {"n": 3, "t": "بل ذلك من فعل ملائكة السماوات إذا مرت بها المعقبات؛ فزعا أن يكون حدث أمر الساعة", "taqdim": 0, "n_athar": 1, "qailun": [], "athar": []}, {"n": 4, "t": "بل الموصوفون بذلك المشركون، قالوا: وإنما يفزع الشيطان عن قلوبهم. قال: وإنما يقولون: ماذا قال ربكم؟ عند نزول المنية بهم", "taqdim": 0, "n_athar": 1, "qailun": [["ابن زيد", "تابع التابعين"]], "athar": [63486]}]}, "mawaqif": [{"taliq": 5331, "mi": 1, "aya": 23, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "19/ 281", "qawl": "الأول", "nass": "وأولى الأقوال في ذلك بالصواب وأشبهها بظاهر التنزيل القول الذي ذكره الشعبي عن ابن مسعود؛ لصحة الخبر الذي ذكرناه عن ابن عباس عن رسول الله صلى الله عليه وسلم بتأييده", "qawaid": ["السنة", "السياق"], "tabi": ""}, {"taliq": 5331, "mi": 1, "aya": 23, "alam": "ابن تيمية", "fil": "وبنحوه", "kind": "موافقة", "ref": "5/ 288 - 297", "qawl": "", "nass": "وبهذا المعنى من ذكر الملائكة في صدر الآيات تتسق هذه الآية على الأولى", "qawaid": ["السياق"], "tabi": "ابن جرير"}, {"taliq": 5331, "mi": 1, "aya": 23, "alam": "ابن عطية", "fil": "وكذا", "kind": "موافقة", "ref": "7/ 183", "qawl": "", "nass": "وبهذا المعنى من ذكر الملائكة في صدر الآيات تتسق هذه الآية على الأولى", "qawaid": ["السياق"], "tabi": "ابن تيمية"}, {"taliq": 5331, "mi": 1, "aya": 23, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "", "qawl": "", "nass": "ومن لم يشعر أن الملائكة مشار إليهم من أول قوله: {الذين زعمتم} لم تتصل له هذه الآية بما قبلها، فلذلك اضطرب المفسرون في تفسيرها", "qawaid": [], "tabi": ""}], "mushid": {"i": 5, "imgs": ["034_005_1.png"], "pages": [425], "n": 4, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 5331, "masala": "من عنى الله بقوله: {حتى إذا فزع عن قلوبهم}، وفي السبب الذي من أجله فزع عن قلوبهم؛", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أن الذي فزع عن قلوبهم الملائكة، قالوا: وإنما يفزع عن قلوبهم من غشية تصيبهم عند سماعهم الله بالوحي", "ashab": "", "athar": []}, {"n": 2, "t": "أن الموصوفين بذلك الملائكة، إنما يفزع عن قلوبهم فزعهم من قضاء الله الذي يقضيه حذرا أن يكون ذلك قيام الساعة", "ashab": "", "athar": []}, {"n": 3, "t": "أن ذلك من فعل ملائكة السموات إذا مرت بها المعقبات؛ فزعا أن يكون حدث أمر الساعة", "ashab": "", "athar": []}, {"n": 4, "t": "أن الموصوفين بذلك المشركون، قالوا: وإنما يفزع الشيطان عن قلوبهم، قال: وإنما يقولون: ماذا قال ربكم؟ عند نزول المنية بهم", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"], ["ابن تيمية", "r"], ["ابن عطية", "r"]]}, "t": {"1": [["ابن جرير", "r"], ["ابن تيمية", "r"], ["ابن عطية", "r"]]}, "gen": [], "rules": {"ابن جرير": ["السنة", "السياق"], "ابن تيمية": ["السياق"], "ابن عطية": ["السياق"]}, "rulesD": {}}}, {"aya": 23, "title": "قوله: {إلا لمن أذن له}", "mawsua": {"taliq": 5326, "masala": "قوله: {إلا لمن أذن له}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "معناه: لمن أذن له أن يشفع فيه", "ashab": "", "athar": []}, {"n": 2, "t": "معناه: لمن أذن له أن يشفع هو", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5326, "mi": 1, "aya": 23, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 183", "qawl": "", "nass": "واختلف المتأولون في قوله تعالى: {إلا لمن أذن له}؛ فقالت فرقة: معناه: لمن أذن له أن يشفع فيه. وقالت فرقة: معناه: لمن أذن له أن يشفع هو", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 24, "title": "في وجه دخول \"أو\" في هذا الموضع ﴿وإنا أو إياكم﴾", "tabari": {"page": "19/284", "sarih": 1, "tarjih": "والصواب من القول في ذلك عندى ، أن ذلك أمر من الله نبيه بتكذيب من أمره بخطابه بهذا القول، بأحسن التكذيب، كما يقول الرجل لصاحب له يخاطبه، وهو يريد تكذيبه في خبر له: أحدنا كاذب. وقائل ذلك يعنى صاحبه لا نفسه؛ فلهذا المعنى صير الكلام ب \"أو\" .", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "ليس ذلك لأنه شك، ولكن هذا في كلام العرب على أنه هو المهتدى. قال: وقد يقول الرجل لعبده: أحدنا ضارب صاحبه. ولا يكون فيه إشكال على السامع، أن المولى هو الضارب", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "معنى ذلك: إنا لعلى هدى، وإنكم إياكم في ضلال مبين؛ لأن العرب تضع \"أو\" في موضع \"واو\" الموالاة. قال جرير :", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 3, "t": "معنى \"أو\" معنى \"الواو\" في هذا الموضع ، غير أن العربية على غير ذلك؛ لا تكون \"أو\" بمنزلة \"الواو\"، ولكنها تكون في الأمر المفوض ، كما تقول: إن شئت فخذ درهما أو اثنين. فله أن يأخذ اثنين أو واحدا، وليس له أن يأخذ ثلاثة. قال: وهو في قول من لا يبصر العربية ويجعل \"أو\" بمنزلة \"الواو\" ، يجوز له أن يأخذ ثلاثة؛ لأنه في قولهم بمنزلة قولك: خذ درهما واثنين. قال: والمعنى في: ﴿إنا أو إياكم﴾: إنا لضالون أو مهتدون، وإنكم أيضا لضالون [أو", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 5332, "mi": 0, "aya": 24, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "19/ 286", "qawl": "", "nass": "أن ذلك أمر من الله نبيه بتكذيب من أمره بخطابه بهذا القول بأحسن التكذيب، كما يقول الرجل لصاحب له يخاطبه وهو يريد تكذيبه في خبر له: أحدنا كاذب. وقائل ذلك يعني صاحبه لا نفسه؛ فلهذا المعنى صير الكلام ب {أو}", "qawaid": [], "tabi": ""}, {"taliq": 5332, "mi": 0, "aya": 24, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 185 - 186", "qawl": "", "nass": "تلطف في الدعوى والمحاورة، والمعنى كما تقول لمن خالفك في مسألة: أحدنا يخطئ. أي: تثبت وتنبه، والمفهوم من كلامك أن مخالفك هو المخطئ، وكذلك هذا معناه {لعلى هدى أو في ضلال مبين} فلنتبينه، والمقصد: أن الضلال في حيز المخاطبين، وحذف أحد الخبرين لدلالة الباقي عليه", "qawaid": ["ظاهر الآية ولفظها"], "tabi": ""}], "mushid": {"i": 6, "imgs": ["034_006_1.png"], "pages": [425], "n": 2, "rajih": [1], "daif": [], "match": false}, "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {}, "rulesD": {}}}, {"aya": 45, "title": "معنى قوله تعالى", "mawsua": {"taliq": 5343, "masala": "معنى قوله تعالى", "sigha": "ذكر ثلاثة أقوال", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يعود الضمير في {بلغوا} على قريش، وفي {آتيناهم} على الأمم الذين من قبلهم", "ashab": "", "athar": []}, {"n": 2, "t": "بعكس القول الأول، ووجهه بقوله: «والمعنى: من الآيات والبيان والنور الذي جئتهم به", "ashab": "", "athar": []}, {"n": 3, "t": "أن يعود الضميران على الأمم المتقدمة، ووجهه بقوله: «والمعنى: من شكر النعمة، وجزاء المنة", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5343, "mi": 1, "aya": 45, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 193، 194", "qawl": "", "nass": "والمعنى: من القوة والنعم والظهور في الدنيا", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 46, "title": "تأويل: ﴿أن تقوموا لله مثنى وفرادى﴾", "tabari": {"page": "19/305", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿أن تقوموا لله مثنى وفرادى﴾. يقول: وتلك الواحدة التي أعظكم بها؛ هي أن تقوموا لله اثنين اثنين، [وفردا فردا] ، ف ﴿أن﴾ في موضع خفض، ترجمة [عن الواحدة] .", "taqdim": 1, "n_athar": 2, "qailun": [["مجاهد", "تابعي"], ["قتادة", "تابعي"]], "athar": [63634, 63635, 63636, 63642, 63643, 63648]}, {"n": 2, "t": "إنما قيل: ﴿إنما أعظكم بواحدة﴾ وتلك الواحدة أن تقوموا لله بالنصيحة وترك الهوى، ﴿مثنى﴾. يقول : يقوم الرجل منكم مع آخر، فيتصادقان على المناظرة؛ هل علمتم بمحمد ﷺ جنونا قط؟ ثم ينفرد كل واحد منكم، فيتفكر ويعتبر فردا ؛ هل كان ذلك به ؟ فتعلموا حينئذ أنه نذير لكم", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 5346, "mi": 1, "aya": 46, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 194", "qawl": "", "nass": "وقوله: {تقوموا لله مثنى وفرادى} يحتمل أن يريد بالطاعة والإخلاص والعبادة، فتكون الواحدة التي وعظ بها هذه، ثم عطف عليها أن تتفكروا في أمره هو، هل به جنة أو هو بريء من ذلك؟ والوقف عند أبي حاتم {تتفكروا}، فيجيء {ما بصاحبكم} نفيا مستأنفا، وهو عند سيبويه جواب ما تنزل منزلة القسم؛ لأن", "qawaid": [], "tabi": ""}, {"taliq": 5346, "mi": 1, "aya": 46, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "", "qawl": "", "nass": "ويحتمل أن يريد بقيامهم: أن يكون لوجه الله في معنى التفكير في محمد عليه الصلاة والسلام، فتكون الواحدة التي وعظ بها {أن تقوموا}، والمعنى: الفكرة: أن تقوموا للفكرة في أمر صاحبهم، وكأن المعنى: أن يفكر الواحد بينه وبين نفسه، وتتناظم الآيتان على جهة طلب التحقيق هل بمحمد صلى الله عليه وسلم جنة أم لا؟ وعلى هذا لا يوقف على الفكرة", "qawaid": [], "tabi": ""}], "mushid": {"i": 7, "imgs": ["034_007_1.png"], "pages": [425], "n": 2, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 5346, "masala": "معنى «الواحدة» التي وعظوا بها", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": []}, "tags": {"m": {}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 51, "title": "في المعنيين بهذه الآية", "tabari": {"page": "19/309", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "عنى بها هؤلاء المشركين الذين وصفهم تعالى ذكره بقوله: ﴿وإذا تتلى عليهم آياتنا بينات قالوا ما هذا إلا رجل يريد أن يصدكم عما كان يعبد آباؤكم﴾. قالوا : وعنى بقوله: ﴿إذ فزعوا فلا فوت وأخذوا من مكان قريب﴾: عند نزول نقمة الله بهم في الدنيا", "taqdim": 0, "n_athar": 3, "qailun": [["ابن عباس", "صحابي"], ["ابن زيد", "تابع التابعين"]], "athar": [63677, 63681, 63682]}, {"n": 2, "t": "عنى بذلك جيش يخسف به ببيداء من الأرض", "taqdim": 0, "n_athar": 3, "qailun": [["سعيد", "تابعي"]], "athar": [63684, 63691]}, {"n": 3, "t": "بل عنى بذلك المشركون، إذا فزعوا عند خروجهم من قبورهم", "taqdim": 0, "n_athar": 3, "qailun": [["الحسن", "تابعي"], ["ابن معقل", ""], ["الضحاك", "تابعي"]], "athar": [63683, 63687, 63689, 63690, 63692, 63693, 63694]}]}, "mawaqif": [{"taliq": 5350, "mi": 1, "aya": 51, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "19/ 313", "qawl": "الأول", "nass": "والذي هو أولى بالصواب في تأويل ذلك، وأشبه بما دل عليه ظاهر التنزيل: قول من قال: ذلك وعيد الله المشركين الذين كذبوا رسول الله صلى الله عليه وسلم من قومه؛ لأن الآيات قبل هذه الآية بالإخبار عنهم وعن إساءتهم، وبوعيد الله إياهم مضت، وهذه الآية في سياق تلك الآيات، فلأن يكون ذلك خبرا عن حالهم أشبه منه بأن يكون خبرا عما لم يجر له ذكر، وإذ كان ذلك كذلك فتأويل الكلام: ولو ترى -يا محمد- هؤلاء المشركين من قومك، فتعاينهم حين فزعوا من معاينتهم عذاب الله {فلا فوت}", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 5350, "mi": 1, "aya": 51, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "7/ 196", "qawl": "الثاني", "nass": "وهذا أرجح الأقوال عندي", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}, {"taliq": 5350, "mi": 1, "aya": 51, "alam": "ابن كثير", "fil": "وبنحوه", "kind": "موافقة", "ref": "11/ 299 بتصرف", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن عطية"}, {"taliq": 5350, "mi": 1, "aya": 51, "alam": "ابن جرير", "fil": "أورد", "kind": "نقل", "ref": "", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 5350, "mi": 1, "aya": 51, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "", "qawl": "الأول", "nass": "والصحيح أن المراد بذلك يوم القيامة، وهو الطامة العظمى، وإن كان ما ذكر متصلا بذلك", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}], "mushid": {"i": 8, "imgs": ["034_008_1.png"], "pages": [426], "n": 3, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 5350, "masala": "المعنيين بقوله تعالى: {ولو ترى إذ فزعوا فلا فوت}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "عني بها المشركون عند نزول نقمة الله بهم في الدنيا", "ashab": "", "athar": []}, {"n": 2, "t": "عني بذلك المشركون إذا فزعوا عند خروجهم من قبورهم", "ashab": "", "athar": []}, {"n": 3, "t": "عني بذلك جيش يخسف به ببيداء من الأرض", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]], "2": [["ابن عطية", "r"], ["ابن كثير", "r"]]}, "t": {"1": [["ابن جرير", "r"]], "3": [["ابن عطية", "r"], ["ابن كثير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["السياق"], "ابن عطية": ["لم يذكر مستندًا"]}, "rulesD": {}}}, {"aya": 52, "title": "قراءة قوله تعالى: {وأنى لهم التناوش}", "mawsua": {"taliq": 5351, "masala": "قراءة قوله تعالى: {وأنى لهم التناوش}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "{التناوش} بغير همز، بمعنى: التناول", "ashab": "", "athar": []}, {"n": 2, "t": "التنآؤش» بالهمز، بمعنى: النئيش، وهو الإبطاء", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5351, "mi": 1, "aya": 52, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "19/ 316", "qawl": "", "nass": "والصواب من القول في ذلك عندي أن يقال: إنهما قراءتان معروفتان في قرأة الأمصار، متقاربتا المعنى. وذلك أن معنى ذلك: وقالوا آمنا بالله في حين لا ينفعهم قيل ذلك. فقال الله: {وأنى لهم التناوش} وأنى لهم التوبة والرجعة التي قد بعدت منهم، وصاروا منها بموضع بعيد أن يتناولوها؛ وإنما وصف ذلك المكان بالبعد لأنهم قالوا ذلك في القيامة، فقال الله: أنى لهم بالتوبة المقبولة؟ والتوبة المقبولة إنما كانت في الدنيا، وقد ذهبت الدنيا، فصارت بعيدا من الآخرة، فبأية القراءتين اللتين ذكرت قرأ القارئ فمصيب الصواب في ذلك", "qawaid": [], "tabi": ""}, {"taliq": 5351, "mi": 1, "aya": 52, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "7/ 197", "qawl": "", "nass": "فكأنه قال: وأنى لهم تناول مرادهم، وقد بعدوا عن مكان إمكان ذلك", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {}, "rulesD": {}}}, {"aya": 54, "title": "تأويل: ﴿وحيل بينهم وبين ما يشتهون كما فعل بأشياعهم من قبل إنهم كانوا في شك مريب﴾", "tabari": {"page": "19/322", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "يقول تعالى ذكره: وحيل بين هؤلاء المشركين - حين فزعوا فلا فوت، وأخذوا من مكان قريب، فقالوا: آمنا به - وبين ما يشتهون حينئد من الإيمان بما كانوا به في الدنيا، قبل ذلك، يكفرون، فلا سبيل لهم إليه.", "taqdim": 1, "n_athar": 6, "qailun": [["الحسن", "تابعي"], ["هذه الآية", ""], ["مجاهد", "تابعي"], ["قتادة", "تابعي"]], "athar": [63734, 63735, 63736, 63738, 63745, 63746, 63751]}, {"n": 2, "t": "معنى ذلك: وحيل بينهم وبين ما يشتهون، من مال وولد وزهرة الدنيا", "taqdim": 0, "n_athar": 2, "qailun": [["مجاهد", "تابعي"], ["ابن زيد", "تابع التابعين"]], "athar": [63734, 63735, 63741, 63745]}]}, "mawaqif": [{"taliq": 5355, "mi": 1, "aya": 54, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "19/ 323", "qawl": "الأول", "nass": "لأن القوم إنما تمنوا -حين عاينوا من عذاب الله ما عاينوا- ما أخبر الله عنهم أنهم تمنوه، وقالوا آمنا به، فقال الله: وأنى لهم تناوش ذلك من مكان بعيد وقد كفروا من قبل ذلك في الدنيا. فإذ كان ذلك كذلك فلأن يكون قوله: {وحيل بينهم وبين ما يشتهون} خبرا عن أنه لا سبيل لهم إلى ما تمنوه أولى من أن يكون خبرا عن غيره", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 5355, "mi": 1, "aya": 54, "alam": "ابن كثير", "fil": "رجح", "kind": "ترجيح", "ref": "11/ 300", "qawl": "الجمع بين", "nass": "والصحيح أنه لا منافاة بين القولين، فإنه قد حيل بينهم وبين شهواتهم في الدنيا وبين ما طلبوه في الآخرة، فمنعوا منه", "qawaid": [], "tabi": ""}, {"taliq": 5355, "mi": 1, "aya": 54, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 198", "qawl": "", "nass": "وهذا يتمكن جدا على القول بأن الأخذ والفزع المذكور هو يوم القيامة", "qawaid": [], "tabi": ""}], "mushid": {"i": 9, "imgs": ["034_009_1.png"], "pages": [426], "n": 2, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 5355, "masala": "معنى: {وحيل بينهم وبين ما يشتهون}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "وحيل بينهم وبين ما يشتهون من الإيمان بما كانوا به في الدنيا يكفرون", "ashab": "", "athar": []}, {"n": 2, "t": "وحيل بينهم وبين ما يشتهون من مال وولد وزهرة الدنيا", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [["ابن كثير", "رجّح الجمع بين"]], "rules": {"ابن جرير": ["السياق"]}, "rulesD": {}}}], "extra": [{"i": 4, "aya": 16, "imgs": ["034_004_1.png"], "pages": [425], "ihala": 0}], "others": {"1": [{"id": 5287, "kinds": "بيان،نقل", "text": "ذكر ابنُ عطية (7/ 155) في قوله: {وله الحمد في الآخرة} ما جاء في قول مقاتل، وبيّن احتمالَ الآية وجهًا آخر، فقال: «وقوله تعالى: {وله الحمد في الآخرة} يحتمل أن تكون الألف واللام للجنس أيضًا، وتكون الآية خبرًا أن الحمد في الآخرة هو له وحده لإنعامه، وإفضاله، وتغمده، وظهور قدرته، وغير ذلك من صفاته».", "mawaqif": [{"taliq": 5287, "mi": 0, "aya": 1, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 155", "qawl": "مقاتل", "nass": "وقوله تعالى: {وله الحمد في الآخرة} يحتمل أن تكون الألف واللام للجنس أيضا، وتكون الآية خبرا أن الحمد في الآخرة هو له وحده لإنعامه، وإفضاله، وتغمده، وظهور قدرته، وغير ذلك من صفاته", "qawaid": [], "tabi": ""}]}, {"id": 5288, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (19/ 208) غير قول قتادة.", "mawaqif": []}], "3": [{"id": 5289, "kinds": "ترجيح،تعليق،نقل", "text": "ذكر ابنُ جرير (19/ 210) عن عامة قراء الكوفة أنهم قرءوا ذلك «عَلّامِ»، ثم علّق عليها وعلى قراءة {عالم} بالرفع والجر، فقال: «والصواب من القول في ذلك عندنا: أن كل هذه القراءات الثلاث قراءات مشهورات في قراء الأمصار متقاربات المعاني، فبأيتهن قرأ القارئ فمصيب». ورجّح مستندًا إلى اللغة هذه القراءة بقوله: «غير أن أعجب القراءات في ذلك إلي أن أقرأ بها: «عَلّامِ الغَيْبِ» على القراءة التي ذكرتها عن عامة قراء أهل الكوفة؛ فأما اختيار «عَلّامِ» على {عالم} فلأنها أبلغ في المدح، وأما الخفض فيها فلأنها من نعت الرب، وهو في موضع الجر، وعنى بقوله: «عَلّامِ الغَيْبِ»: علام ما يغيب عن أبصار الخلق، فلا يراه أحد، إما ما لم يكونه مما سيكونه، أو ما قد كونه فلم يطْلع عليه أحدًا غيره».\nوقال ابنُ عطية (7/ 157): «وقرأ ابن كثير وأبو عمرو والكسائي بخلاف {عالم} بالخفض على البدل من رَبِّي، وقرأ نافع وابن عامر «عالِمُ» بالرفع على القطع، أي: هو عالم، ويصح أن يكون «عالِمُ» رفع بالابتداء، وخبره {لا يَعْزُبُ} وما بعده، ويكون الإخبار بأن العالِم لا يعزب عنه شيء إشارة إلى أنه قد قدَّر وقتها وعلِمَه، والوجه الأول أقرب».", "mawaqif": [{"taliq": 5289, "mi": 0, "aya": 3, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "19/ 210", "qawl": "", "nass": "علام", "qawaid": ["القراءة ورسم المصحف"], "tabi": ""}, {"taliq": 5289, "mi": 0, "aya": 3, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 157", "qawl": "", "nass": "وقرأ ابن كثير وأبو عمرو والكسائي بخلاف {عالم} بالخفض على البدل من ربي، وقرأ نافع وابن عامر «عالم", "qawaid": [], "tabi": ""}]}], "5": [{"id": 5290, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (19/ 213) غير قول ابن زيد، وقول قتادة.", "mawaqif": []}], "8": [{"id": 5291, "kinds": "نقل", "text": "أورد ابنُ عطية (7/ 159) في قوله تعالى: {في العذاب} احتمالين، فقال: «{فِي العَذابِ} يريد: عذاب الآخرة؛ لأنهم يصيرون إليه. ويحتمل أن يريد: في العذاب في الدنيا بمكابدة الشرع ومكايدته، ومحاولة إطفاء نور الله تعالى، وهو يتم، وهذا كله عذاب».", "mawaqif": [{"taliq": 5291, "mi": 0, "aya": 8, "alam": "ابن عطية", "fil": "أورد", "kind": "نقل", "ref": "7/ 159", "qawl": "", "nass": "{في العذاب} يريد: عذاب الآخرة؛ لأنهم يصيرون إليه. ويحتمل أن يريد: في العذاب في الدنيا بمكابدة الشرع ومكايدته، ومحاولة إطفاء نور الله تعالى، وهو يتم، وهذا كله عذاب", "qawaid": [], "tabi": ""}]}], "10": [{"id": 5292, "kinds": "نقل", "text": "قال ابن جرير (19/ 221): «وفي نصب الطير وجهان: أحدهما: على ما قاله ابن زيد مِن أن الطير نُودِيت كما نوديت الجبال، فتكون منصوبة مِن أجل أنها معطوفة على مرفوع بما لا يحسن إعادة رافعه عليه، فيكون كالمصدر عن جهته. والآخر: فعل ضمير متروك استغني بدلالة الكلام عليه، فيكون معنى الكلام: فقلنا: يا جبال، أوبي معه، وسخرنا له الطير. وإن رفع ردًّا على ما في قوله:» سبحي\" من ذكر الجبال كان جائزًا، وقد يجوز رفع الطير وهو معطوف على الجبال، وإن لم يحسن نداؤها بالذي نوديت به الجبال، فيكون ذلك كما قال الشاعر:\nألا يا عمرو والضحاك سيرا … فقد جاوزتما خمر الطريق\".", "mawaqif": [{"taliq": 5292, "mi": 0, "aya": 10, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "19/ 221", "qawl": "", "nass": "وفي نصب الطير وجهان: أحدهما: على ما قاله ابن زيد من أن الطير نوديت كما نوديت الجبال، فتكون منصوبة من أجل أنها معطوفة على مرفوع بما لا يحسن إعادة رافعه عليه، فيكون كالمصدر عن جهته. والآخر: فعل ضمير متروك استغني بدلالة الكلام عليه، فيكون معنى الكلام: فقلنا: يا جبال، أوبي معه، وسخرنا له الطير. وإن رفع ردا على ما في قوله:", "qawaid": [], "tabi": ""}]}, {"id": 5293, "kinds": "غيره", "text": "قال ابنُ عطية (7/ 160 - 161) معلِّقًا على قول ابن عباس: «{وأَوِّبِي} معناه: رجِّعي معه؛ لأنه مضاعف آب يؤوب، فقال ابن عباس وقتادة وابن زيد وغيرهم معناه: سبحي معه، أي: يسبح هو وترجع هي معه التسبيح، أي: تردُّ بالذكر، ثم ضوعف الفعل للمبالغة».", "mawaqif": [{"taliq": 5293, "mi": 0, "aya": 10, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 160 - 161", "qawl": "ابن عباس", "nass": "{وأوبي} معناه: رجعي معه؛ لأنه مضاعف آب يؤوب، فقال ابن عباس وقتادة وابن زيد وغيرهم معناه: سبحي معه، أي: يسبح هو وترجع هي معه التسبيح، أي: ترد بالذكر، ثم ضوعف الفعل للمبالغة", "qawaid": [], "tabi": ""}]}, {"id": 5294, "kinds": "نقد،تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 161) مثل هذا القول عن مؤرج، وعلَّق عليه قائلًا: «وهذا ضعيف غير معروف».\nوانتقده ابنُ كثير (11/ 262) مستندًا إلى اللغة بقوله: «وفي هذا نظر؛ فإن التأويب في اللغة هو الترجيع، فأمرت الجبال والطير أن تُرَجِّع معه بأصواتها».", "mawaqif": [{"taliq": 5294, "mi": 0, "aya": 10, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 161", "qawl": "عن مؤرج", "nass": "وهذا ضعيف غير معروف", "qawaid": [], "tabi": ""}, {"taliq": 5294, "mi": 0, "aya": 10, "alam": "ابن كثير", "fil": "انتقده", "kind": "نقد", "ref": "11/ 262", "qawl": "", "nass": "وفي هذا نظر؛ فإن التأويب في اللغة هو الترجيع، فأمرت الجبال والطير أن ترجع معه بأصواتها", "qawaid": ["اللغة"], "tabi": ""}]}, {"id": 5295, "kinds": "نقد،نقل", "text": "ذكر ابنُ عطية (7/ 161) إضافة إلى ما ورد في آثار السلف في معنى: {أوبي} قولًا، ووجّهه، فقال: \"وقيل: معناه: سيري معه؛ لأن التأويب سير النهار، كأن الإنسان يسير بالليل ثم يرجِّع السير بالنهار، أي: يردده، فكأنه يُؤَوِّبه، فقيل له: التأويب، ومنه قول الشاعر:\nيومان يوم مقامات وأندية … ويوم سير إلى الأعداء تأويب\".", "mawaqif": [{"taliq": 5295, "mi": 0, "aya": 10, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 161", "qawl": "الشاعر", "nass": "", "qawaid": [], "tabi": ""}]}], "12": [{"id": 5297, "kinds": "ترجيح،تعليق،نقل", "text": "ذكر ابنُ جرير (19/ 226) هذه القراءة وقراءة النصب في {الريح}، ورجّحها مستندًا إلى إجماع الحجة من القراء.\nوعلّق ابنُ عطية (7/ 164) على هذه القراءة، فقال: «وقرأ عاصم في رواية أبي بكر والأعرج {الريحُ} بالرفع على تقدير: تسخرت الريح، أو على الابتداء، والخبر في المجرور، وذلك على حذف مضاف تقديره: ولسليمان تسخير الريح».", "mawaqif": [{"taliq": 5297, "mi": 0, "aya": 12, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "19/ 226", "qawl": "", "nass": "", "qawaid": ["القراءة ورسم المصحف"], "tabi": ""}, {"taliq": 5297, "mi": 0, "aya": 12, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 164", "qawl": "", "nass": "وقرأ عاصم في رواية أبي بكر والأعرج {الريح} بالرفع على تقدير: تسخرت الريح، أو على الابتداء، والخبر في المجرور، وذلك على حذف مضاف تقديره: ولسليمان تسخير الريح", "qawaid": [], "tabi": ""}]}, {"id": 5298, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 165) نحو ما جاء في قول ابن زيد، وعلّق عليه، فقال: «وكانت الأعصار تُقِلُّ بساطَه وتحمله بعد ذلك الرخاء، وكان هذا البساط يحمل -فيما روي- أربعة آلاف فارس، وما يشبهها من الرجال والعُدد، ويتسع لهم، وروي أكثر من هذا بكثير، ولكن عدم صحته مع بُعد شبهه أوجب اختصاره».", "mawaqif": [{"taliq": 5298, "mi": 0, "aya": 12, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 165", "qawl": "ابن زيد", "nass": "وكانت الأعصار تقل بساطه وتحمله بعد ذلك الرخاء، وكان هذا البساط يحمل -فيما روي- أربعة آلاف فارس، وما يشبهها من الرجال والعدد، ويتسع لهم، وروي أكثر من هذا بكثير، ولكن عدم صحته مع بعد شبهه أوجب اختصاره", "qawaid": [], "tabi": ""}]}, {"id": 5299, "kinds": "نقل", "text": "ذكر ابنُ عطية (4/ 409) قول قتادة وقول ابن عباس، ثم قال: «وقالت فرقة: القطر: الفلز كله؛ النحاس، والحديد، وما جرى مجراه، كان يسيل له منه عيون. وقالت فرقة: بل معنى {وأسلنا له عين القطر}: أذبنا له النحاس عن نحوِ ما كان الحديد يلين لداود، قالوا: وكانت الأعمال تتأتى منه لسليمان وهو بارد دون نار. وعين على هذا التأويل بمعنى: المذاب».", "mawaqif": [{"taliq": 5299, "mi": 0, "aya": 12, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "4/ 409", "qawl": "قتادة وقول", "nass": "وقالت فرقة: القطر: الفلز كله؛ النحاس، والحديد، وما جرى مجراه، كان يسيل له منه عيون. وقالت فرقة: بل معنى {وأسلنا له عين القطر}: أذبنا له النحاس عن نحو ما كان الحديد يلين لداود، قالوا: وكانت الأعمال تتأتى منه لسليمان وهو بارد دون نار. وعين على هذا التأويل بمعنى: المذاب", "qawaid": [], "tabi": ""}]}, {"id": 5300, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (19/ 229) غير قول قتادة.", "mawaqif": []}], "13": [{"id": 5301, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 166) نحو قول الحسن والضحاك، وعلّق عليه بقوله: «وقال الضحاك: كانت تماثيل حيوان، وكان هذا من الجائز في ذلك الشرع، ونسخ بشرع محمد صلى الله عليه وسلم. وقال قوم: حرم التصوير؛ لأن الصور كانت تُعبد. وحكى مكي في الهداية: أنّ فرقة تجوِّز التصوير وتحتج بهذه الآية. وذلك خطأ، وما أحفظ من أئمة العلم مَن يُجَوِّزه».", "mawaqif": [{"taliq": 5301, "mi": 0, "aya": 13, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 166", "qawl": "الحسن والضحاك", "nass": "وقال الضحاك: كانت تماثيل حيوان، وكان هذا من الجائز في ذلك الشرع، ونسخ بشرع محمد صلى الله عليه وسلم. وقال قوم: حرم التصوير؛ لأن الصور كانت تعبد. وحكى مكي في الهداية: أن فرقة تجوز التصوير وتحتج بهذه الآية. وذلك خطأ، وما أحفظ من أئمة العلم من يجوزه", "qawaid": [], "tabi": ""}]}, {"id": 5302, "kinds": "توجيه،نقل", "text": "ذكر ابنُ عطية (7/ 167) ما جاء في قول مجاهد، وانتقده، فقال: «وقال مجاهد: هي جمع جوْبة، وهي الحفرة العظيمة من الأرض. وفي هذا نظر». ثم قال: \"ومنه قول الأعشى:\nنفى الذم عن آل المحلق جفنة كجابية الشيخ العراقي تفهق\".", "mawaqif": [{"taliq": 5302, "mi": 0, "aya": 13, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 167", "qawl": "مجاهد", "nass": "وقال مجاهد: هي جمع جوبة، وهي الحفرة العظيمة من الأرض. وفي هذا نظر", "qawaid": [], "tabi": ""}]}, {"id": 5303, "kinds": "تعليق،نقل", "text": "علّق ابن جرير (19/ 243) على قراءة ابن عباس، فقال: «و {أن} في قوله: {أن لو كانوا} في موضع رفع بـ (تبين)؛ لأن معنى الكلام: فلما خر تبين وانكشف أن لو كان الجن يعلمون الغيب ما لبثوا في العذاب المهين. وأما على التأويل الذي تأوله ابن عباس من أن معناه: تبينت الإنس الجن. فإنه ينبغي أن تكون {أن} في موضع نصب بتكريرها على {الجن}، وكذلك يجب على هذه القراءة أن تكون {الجن} منصوبة، غير أني لا أعلم أحدًا من قرأة الأمصار يقرأ ذلك بنصب {الجن}، ولو نُصبت كان في قوله: {تبينت} ضمير من ذكر الإنس».", "mawaqif": [{"taliq": 5303, "mi": 0, "aya": 13, "alam": "ابن جرير", "fil": "علق", "kind": "تعليق", "ref": "19/ 243", "qawl": "", "nass": "و {أن} في قوله: {أن لو كانوا} في موضع رفع ب (تبين)؛ لأن معنى الكلام: فلما خر تبين وانكشف أن لو كان الجن يعلمون الغيب ما لبثوا في العذاب المهين. وأما على التأويل الذي تأوله ابن عباس من أن معناه: تبينت الإنس الجن. فإنه ينبغي أن تكون {أن} في موضع نصب بتكريرها على {الجن}، وكذلك يجب على هذه القراءة أن تكون {الجن} منصوبة، غير أني لا أعلم أحدا من قرأة الأمصار يقرأ ذلك بنصب {الجن}، ولو نصبت كان في قوله: {تبينت} ضمير من ذكر الإنس", "qawaid": [], "tabi": ""}]}], "14": [{"id": 5304, "kinds": "خلاف،نقل", "text": "قال ابنُ عطية (7/ 170): «وقال كثير من المفسرين: {دابَّةُ الأَرْضِ} هي سوسة العود، وهي الأرَضَة، وقرأ ابن عباس والعباس بن المفضل: (الأَرَضِ) بفتح الراء، جمع: أرضة، فهذا يقوي ذلك التأويل». ثم ذكر في معنى الآية قولين آخرين، فقال: «وقالت فرقة: {دابة الأرض} حيوان مِن الأرض شأنه أن يأكل العود، وذلك موجود، وليس السوسة من دواب الأرض. وقالت فرقة منها أبو حاتم اللغوي: {الأرض} هنا مصدر: أرضت الأثواب والخشبة؛ إذا أكلتها الأرضة، فكأنه قال: دابة الأكل الذي هو بتلك الصورة على جهة التسوس».", "mawaqif": [{"taliq": 5304, "mi": 0, "aya": 14, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 170", "qawl": "", "nass": "وقال كثير من المفسرين: {دابة الأرض} هي سوسة العود، وهي الأرضة، وقرأ ابن عباس والعباس بن المفضل: (الأرض) بفتح الراء، جمع: أرضة، فهذا يقوي ذلك التأويل", "qawaid": [], "tabi": ""}]}, {"id": 5305, "kinds": "تعليق", "text": "علّق ابنُ كثير (116/ 269) على هذا الأثر فقال: «وهذا الأثر -والله أعلم-إنّما هو مما تلقي من علماء أهل الكتاب، وهي وقف، لا يصدق منها إلا ما وافق الحق، ولا يكذب منها إلا ما خالف الحق، والباقي لا يصدق ولا يكذب».", "mawaqif": [{"taliq": 5305, "mi": 0, "aya": 14, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "116/ 269", "qawl": "", "nass": "وهذا الأثر -والله أعلم-إنما هو مما تلقي من علماء أهل الكتاب، وهي وقف، لا يصدق منها إلا ما وافق الحق، ولا يكذب منها إلا ما خالف الحق، والباقي لا يصدق ولا يكذب", "qawaid": [], "tabi": ""}]}, {"id": 5306, "kinds": "نقد،نقل", "text": "نقل ابنُ عطية (7/ 171) إضافة إلى ما ورد في آثار السلف في قصة موت سليمان عليه السلام قولًا آخر، فقال: «وقال بعض الناس: إن سليمان عليه السلام لم يمت إلا في سفر مضطجعًا، ولكنه كان في بيت مبني عليه، وأكلت الأرَضَة عتبة الباب حتى خرَّ البيت؛ فعُلم موته». وانتقده بقوله: «وهذا ضعيف». ثمَّ قال ابن عطية عقب هذا: «وأكثرَ المفسرون في قصص هذه الآية بما لا صحة له، ولا تقتضيه ألفاظ القرآن، وفي معانيه بُعْدٌ، فاختصرته لذلك».", "mawaqif": [{"taliq": 5306, "mi": 0, "aya": 14, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "7/ 171", "qawl": "", "nass": "وقال بعض الناس: إن سليمان عليه السلام لم يمت إلا في سفر مضطجعا، ولكنه كان في بيت مبني عليه، وأكلت الأرضة عتبة الباب حتى خر البيت؛ فعلم موته", "qawaid": [], "tabi": ""}, {"taliq": 5306, "mi": 0, "aya": 14, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "", "qawl": "", "nass": "وأكثر المفسرون في قصص هذه الآية بما لا صحة له، ولا تقتضيه ألفاظ القرآن، وفي معانيه بعد، فاختصرته لذلك", "qawaid": [], "tabi": ""}]}, {"id": 5307, "kinds": "غيره", "text": "قال ابنُ عطية (7/ 171 - 172): «وقرأ الجمهور {تَبَيَّنَتِ الجِنُّ} بإسناد الفعل إليها، أي: بان أمرُها، كأنه قال: افتضحت الجنُّ، أي: للإنس، هذا تأويل. ويحتمل أن يكون قوله: {تَبَيَّنَتِ الجِنُّ} بمعنى: علمت الجن وتحققت، ويريد بالجِنّ: جمهورهم والفَعَلة منهم والخَدَمة، ويريد بالضمير في {كانُوا}: رؤساءهم وكبارهم؛ لأنهم هم الذين يدعون علم الغيب لأتباعهم من الجن والإنس ويوهمونهم ذلك. قاله قتادة، فتبين الأتباع أن الرؤوس لَوْ كانُوا عالمين الغيب ما لَبِثُوا، و {أنْ} على التأويل الأول بدل من {الجِنُّ}، وعلى التأويل الثاني مفعولة محضة، وقرأ يعقوب: (تُبُيِّنَتُ الجِنُّ) على بناء الفعل للمفعول، أي: تبينها الناس، و {أنْ} على هذه القراءة بدل، ويجوز أن تكون في موضع نصب بإسقاط حرف الجر، أي: بأن، على هذه القراءة، وعلى التأويل الأول من القراءة الأولى».", "mawaqif": [{"taliq": 5307, "mi": 0, "aya": 14, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 171 - 172", "qawl": "", "nass": "وقرأ الجمهور {تبينت الجن} بإسناد الفعل إليها، أي: بان أمرها، كأنه قال: افتضحت الجن، أي: للإنس، هذا تأويل. ويحتمل أن يكون قوله: {تبينت الجن} بمعنى: علمت الجن وتحققت، ويريد بالجن: جمهورهم والفعلة منهم والخدمة، ويريد بالضمير في {كانوا}: رؤساءهم وكبارهم؛ لأنهم هم الذين يدعون علم الغيب لأتباعهم من الجن والإنس ويوهمونهم ذلك. قاله قتادة، فتبين الأتباع أن الرؤوس لو كانوا عالمين الغيب ما لبثوا، و {أن} على التأويل الأول بدل من {الجن}، وعلى التأويل الثاني مفعولة محضة، وقرأ يعقوب: (تبينت الجن) على بناء الفعل للمفعول، أي: تبينها الناس، و {أن} على هذه القراءة بدل، ويجوز أن تكون في موضع نصب بإسقاط حرف الجر، أي: بأن، على هذه القراءة، وعلى التأويل الأول من القراءة الأولى", "qawaid": [], "tabi": ""}]}], "15": [{"id": 5308, "kinds": "تعليق", "text": "علّق ابنُ جرير (19/ 246) على هذه القراءة بقوله: «قرأته عامة قراء المدينة والبصرة وبعض الكوفيين: «فِي مَساكِنِهِمْ» على الجماع، بمعنى: منازل آل سبأ».", "mawaqif": [{"taliq": 5308, "mi": 0, "aya": 15, "alam": "ابن جرير", "fil": "علق", "kind": "تعليق", "ref": "19/ 246", "qawl": "", "nass": "قرأته عامة قراء المدينة والبصرة وبعض الكوفيين: «في مساكنهم", "qawaid": [], "tabi": ""}]}, {"id": 5309, "kinds": "تعليق", "text": "علّق ابنُ جرير (19/ 246) على قراءتي الجمع والإفراد في قوله: {مسكنهم}، فقال: «والصواب من القول في ذلك عندنا: أن كل ذلك قراءات متقاربات المعنى، فبأي ذلك قرأ القارئ فمصيب».\nوعلّق ابنُ عطية (7/ 173) على قراءة الجمع، فقال: «وقرأ جمهور القراء: «فِي مَساكِنِهِمْ» لأن كل أحد له مسكن». وعلّق على قراءة الإفراد، فقال: «وقرأ الكسائي وحده: «فِي مَسْكِنِهِمْ» بكسر الكاف، أي: في موضع سكناهم، وهي قراءة الأعمش وعلقمة، قال أبو علي: والفتح حسن أيضًا، لكن هذا كما قالوا: مسجد، وإن كان سيبويه يرى هذا اسم البيت، وليس موضع السجود. قال: هي لغة الناس اليوم، والفتح هي لغة الحجاز، وهي اليوم قليلة».", "mawaqif": [{"taliq": 5309, "mi": 0, "aya": 15, "alam": "ابن جرير", "fil": "علق", "kind": "تعليق", "ref": "19/ 246", "qawl": "", "nass": "والصواب من القول في ذلك عندنا: أن كل ذلك قراءات متقاربات المعنى، فبأي ذلك قرأ القارئ فمصيب", "qawaid": [], "tabi": ""}, {"taliq": 5309, "mi": 0, "aya": 15, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 173", "qawl": "", "nass": "وقرأ جمهور القراء: «في مساكنهم", "qawaid": [], "tabi": ""}]}, {"id": 5310, "kinds": "نقل", "text": "قال ابنُ جرير (19/ 246): «فإن كان الأمرُ كما رُوِي عن رسول الله صلى الله عليه وسلم مِن أنّ سبأ رجل، كان الإجراء فيه وغير الإجراء معتدلين، أما الإجراء فعلى أنه اسم رجل معروف، وأما ترك الإجراء فعلى أنه اسم قبيلة أو أرض. وقد قرأ بكل واحدة منهما علماء مِن القراء».", "mawaqif": [{"taliq": 5310, "mi": 0, "aya": 15, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "19/ 246", "qawl": "", "nass": "فإن كان الأمر كما روي عن رسول الله صلى الله عليه وسلم من أن سبأ رجل، كان الإجراء فيه وغير الإجراء معتدلين، أما الإجراء فعلى أنه اسم رجل معروف، وأما ترك الإجراء فعلى أنه اسم قبيلة أو أرض. وقد قرأ بكل واحدة منهما علماء من القراء", "qawaid": [], "tabi": ""}]}], "16": [{"id": 5312, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 175 - 176) عن المغيرة بن حكيم نحو ما جاء في قول وهب من معنى العرم، ثم قال معلَّقًا: \"كأنها الجسور والسداد ونحوها، ومن هذا المعنى قول الأعشى:\nوفي ذاكَ لِلَمُؤتَسِي أُسْوَةٌ ومَأْرِبُ عَضَّ عليها العَرِمْ\nرِخاٌم بَناهُ لهم حِمْيَرٌ إذا جاءَ مَوّارُهُ لم يَرِمْومنه قول الآخر:\nمِن سَبَأ الحاضرِين مَأْرِبُ إذ يَبْنُون من دون سَيْلِه العَرِما\".", "mawaqif": [{"taliq": 5312, "mi": 0, "aya": 16, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 175 - 176", "qawl": "وهب من", "nass": "", "qawaid": [], "tabi": ""}]}, {"id": 5313, "kinds": "تعليق", "text": "علّق ابنُ كثير (11/ 278) على هذا الأثر، فقال: «هذا أثر غريب عجيب، وهذا الكاهن هو عمرو بن عامر أحد رؤساء اليمن، وكبراء سبأ وكهانهم».", "mawaqif": [{"taliq": 5313, "mi": 0, "aya": 16, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "11/ 278", "qawl": "", "nass": "هذا أثر غريب عجيب، وهذا الكاهن هو عمرو بن عامر أحد رؤساء اليمن، وكبراء سبأ وكهانهم", "qawaid": [], "tabi": ""}]}, {"id": 5315, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 176) قول ابن عباس، ثم علّق بقوله: «وكأنه صفة للسيل، مِن العرامة».", "mawaqif": [{"taliq": 5315, "mi": 0, "aya": 16, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 176", "qawl": "ابن عباس", "nass": "وكأنه صفة للسيل، من العرامة", "qawaid": [], "tabi": ""}]}, {"id": 5316, "kinds": "نقد،نقل", "text": "ذكر ابنُ عطية (7/ 176) إضافة إلى ما ورد في أقوال السلف في قوله تعالى: {العرم} قولًا آخر، فقال: «وقيل: {العَرِم} صفة للمطر الشديد الذي كان عند ذلك السيل».", "mawaqif": [{"taliq": 5316, "mi": 0, "aya": 16, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 176", "qawl": "", "nass": "وقيل: {العرم} صفة للمطر الشديد الذي كان عند ذلك السيل", "qawaid": [], "tabi": ""}]}, {"id": 5317, "kinds": "توجيه،نقل", "text": "أفادت آثار السلف أن «الخمط» هو شجر الأراك، وقد ذكر هذا ابنُ عطية (7/ 176)، وزاد قولًا آخر، فقال: «وقيل: الخمط: كل شجر له شوك، وثمرته كريهة الطعم بمرارة، أو حمضة، أو نحوه». ووجّهه بقوله: «ومنه: تخمَّط اللبن: إذا تغير طعمه».", "mawaqif": []}, {"id": 5318, "kinds": "نقل", "text": "قال ابن جرير (19/ 257): «وأما الأثل فإنّه يقال: إنه الطرفاء. وقيل: إنه شجر شبيه بالطرفاء، غير أنه أعظم منها. وقيل: إنه السَّمُر». ثم قال: «ذكر من قال ذلك» وذكر قول ابن عباس ولم يذكر غيره.\nوقال ابنُ عطية (7/ 176): «والأثل: ضربٌ من الطرفاء. هذا هو الصحيح».", "mawaqif": [{"taliq": 5318, "mi": 0, "aya": 16, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "19/ 257", "qawl": "", "nass": "وأما الأثل فإنه يقال: إنه الطرفاء. وقيل: إنه شجر شبيه بالطرفاء، غير أنه أعظم منها. وقيل: إنه السمر", "qawaid": [], "tabi": ""}, {"taliq": 5318, "mi": 0, "aya": 16, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 176", "qawl": "", "nass": "والأثل: ضرب من الطرفاء. هذا هو الصحيح", "qawaid": [], "tabi": ""}]}, {"id": 5319, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (19/ 257) غير قول ابن عباس.", "mawaqif": []}], "17": [{"id": 5320, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (19/ 259 - 260) غير قول قتادة، وقول مجاهد من طريق ابن أبي نجيح.", "mawaqif": []}], "18": [{"id": 5321, "kinds": "غيره", "text": "قال ابنُ عطية (7/ 178): «والقرى التي بورك فيها: هي قرى الشام، بإجماع من المفسرين».", "mawaqif": [{"taliq": 5321, "mi": 0, "aya": 18, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 178", "qawl": "", "nass": "والقرى التي بورك فيها: هي قرى الشام، بإجماع من المفسرين", "qawaid": [], "tabi": ""}]}], "19": [{"id": 5323, "kinds": "خلاف،توجيه،بيان،تعليق،نقل", "text": "ذكر ابنُ جرير (19/ 264 - 265) في قوله: {ربنا باعد بين أسفارنا} أربع قراءات، فقال: «اختلف القرأة في قراءة قوله: {ربنا باعد بين أسفارنا} فقرأته عامة قرأة المدينة والكوفة: {ربنا باعد بين أسفارنا} على وجه الدعاء والمسألة بالألف؛ وقرأ ذلك بعض أهل مكة والبصرة: «بَعِّدْ» بتشديد العين على الدعاء أيضًا، وذكر عن بعض المتقدمين أنه كان يقرؤه: «رَبُّنا باعَدَ بَيْنَ أسْفارِنا» على وجه الخبر عن الله أنّ الله فعل ذلك بهم. وحكي عن آخر أنه قرأه: (رَبَّنا بَعُدَ) على وجه الخبر أيضًا غير أن الربَّ منادى».\nوبنحو توجيه ابن جرير لقراءتي: {باعِدْ} و «باعَدَ» وجّههما ابنُ عطية (7/ 179 - 180).\nثم علّق ابنُ جرير بقوله: «والصواب من القراءة في ذلك عندنا: {ربنا باعد} و «بَعِّدْ»؛ لأنهما القراءتان المعروفتان في قرأة الأمصار، وما عداهما فغير معروف فيهم، على أن التأويل من أهل التأويل أيضًا يحقق قراءة من قرأه على وجه الدعاء والمسألة، وذلك أيضًا مما يزيد القراءة الأخرى بعدًا من الصواب، فإذا كان ذلك كذلك وهو الصواب من القراءة فتأويل الكلام: فقالوا: يا ربنا، باعد بين أسفارنا، فاجعل بيننا وبين الشام فلوات ومفاوز؛ لنركب فيها الرواحل، ونتزود معنا فيها الأزواد».", "mawaqif": [{"taliq": 5323, "mi": 0, "aya": 19, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "19/ 264 - 265", "qawl": "", "nass": "اختلف القرأة في قراءة قوله: {ربنا باعد بين أسفارنا} فقرأته عامة قرأة المدينة والكوفة: {ربنا باعد بين أسفارنا} على وجه الدعاء والمسألة بالألف؛ وقرأ ذلك بعض أهل مكة والبصرة: «بعد", "qawaid": [], "tabi": ""}, {"taliq": 5323, "mi": 0, "aya": 19, "alam": "ابن عطية", "fil": "وجههما", "kind": "توجيه", "ref": "7/ 179 - 180", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 5323, "mi": 0, "aya": 19, "alam": "ابن جرير", "fil": "علق", "kind": "تعليق", "ref": "", "qawl": "", "nass": "والصواب من القراءة في ذلك عندنا: {ربنا باعد} و «بعد", "qawaid": [], "tabi": ""}]}, {"id": 5324, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (19/ 266 - 268) غير قول محمد بن إسحاق، وقول عامر.", "mawaqif": []}], "20": [{"id": 5325, "kinds": "خلاف،بيان،تعليق،نقل", "text": "ذكر ابنُ جرير (19/ 269) قراءة من قرأ {صدَّق} بالتشديد و «صَدَق» بتخفيف الدال، وعلّق عليهما بقوله: «اختلفت القراء في قراءة قوله: {ولقد صدق عليهم إبليس ظنه}؛ فقرأ ذلك عامة قراء الكوفيين: {ولقد صدق} بتشديد الدال من {صدق}، بمعنى أنه قال ظنًا منه: {ولا تجد أكثرهم شاكرين} [الأعراف: 17]، وقال: {فبعزتك لأغوينهم أجمعين إلا عبادك منهم المخلصين} [ص: 82]، ثم صدق ظنه ذلك فيهم، فحقق ذلك بهم، وباتباعهم إياه. وقرأ ذلك عامة قراء المدينة والشام والبصرة: «ولَقَدْ صَدَقَ» بتخفيف الدال، بمعنى: ولقد صدق عليهم ظنه». ثم قال معلّقًا عليهما: «والصواب من القول في ذلك عندي أنهما قراءتان معروفتان متقاربتا المعنى؛ وذلك أن إبليس قد صدق على كفرة بني آدم في ظنه، وصدق عليهم ظنه الذي ظن حين قال: {ثم لآتينهم من بين أيديهم ومن خلفهم وعن أيمانهم وعن شمائلهم ولا تجد أكثرهم شاكرين} [الأعراف: 17]، وحين قال: {ولأضلنهم ولأمنينهم} [النساء: 119] الآية، قال ذلك عدو الله ظنًّا منه أنه يفعل ذلك لا علمًا، فصار ذلك حقًّا باتباعهم إياه، فبأي القراءتين قرأ القارئ فمصيب».\nثم قال موجّهًا معنى الآية على قراءة التشديد: «فتأويل الكلام على قراءة مَن قرأ بتشديد الدال: ولقد ظن إبليس بهؤلاء الذين بدلناهم بجنتيهم جنتين ذواتي أكل خمط، عقوبة منا لهم، ظنًّا غير يقين، علم: أنهم يتبعونه ويطيعونه في معصية الله، فصدق ظنه عليهم، بإغوائه إياهم، حتى أطاعوه، وعصوا ربهم، إلا فريقًا من المؤمنين بالله، فإنهم ثبتوا على طاعة الله ومعصية إبليس».\nوعلّق ابنُ عطية (7/ 181) على القراءتين، فقال: «قرأ نافع وأبو عمرو وابن عامر «ولَقَدْ صَدَقَ» بتخفيف الدال {إبليس} رفعًا {ظنَّه} نصبًا على المصدر، وقيل: على الظرفية، أي: في ظنه، وقيل: على المفعول، على معنى: أنه لما ظن عمل عملًا يصدق به ذلك الظن، فكأنه إنما أراد أن يصدق ظنه، وهذا نحو من قولك: أخطأت ظني، وأصبت ظني. وقرأ عاصم وحمزة والكسائي {صدّق} بتشديد الدال، والظن على هذا مفعول بـ {صدّق}، وهي قراءة ابن عباس وقتادة وطلحة وعاصم والأعمش».", "mawaqif": [{"taliq": 5325, "mi": 0, "aya": 20, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "19/ 269", "qawl": "", "nass": "صدق", "qawaid": [], "tabi": ""}, {"taliq": 5325, "mi": 0, "aya": 20, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 181", "qawl": "", "nass": "قرأ نافع وأبو عمرو وابن عامر «ولقد صدق", "qawaid": [], "tabi": ""}]}], "23": [{"id": 5327, "kinds": "خلاف،تعليق،نقل", "text": "علّق ابنُ جرير (19/ 282) على قراءة الحسن: «وروي عن الحسن أنه قرأ ذلك: (حَتّى إذا فُرِغَ عَن قُلُوبِهِمْ) بالراء والغين على التأويل الذي ذكرناه عن ابن زيد، وقد يحتمل توجيه معنى قراءة الحسن ذلك كذلك إلى: حتى إذا فرغ عن قلوبهم فصارت فارغة من الفزع الذي كان حلَّ بها».\nوذكر ابنُ عطية (7/ 184) عن الحسن في هذه القراءة عدة أوجه، فقال: «وقرأ الحسن البصري بخلاف (فُزِعَ) بضم الفاء وكسر الزاي وتخفيفها، كأنه بمعنى: أقلع، ومن قال بأنها في العالم أجمعه قال: معنى هذه القراءة: فزع الشيطان عن قلوبهم، أي: بادر. وقرأ أيوب عن الحسن أيضًا (فُرِّغَ) بالفاء المضمومة والراء المشددة غير منقوطة والغين المنقوطة من التفريغ، قال أبو حاتم: رواها عن الحسن نحو من عشرة أنفس، وهي قراءة أبي مجلز. وقرأ مطر الوراق عن الحسن: (فُزِعَ) على بناء الفعل للفاعل، وهي قراءة مجاهد، وقرأ الحسن أيضًا (فَرَغَ) بالراء غير منقوطة مخففة من الفراغ، قال أبو حاتم: وما أظن الثقات رووها عن الحسن على وجوه إلا لصعوبة المعنى عليه؛ فاختلفت ألفاظه فيها».\nوعلّق عليها ابنُ كثير (11/ 282) على قراءة الحسن المذكورة، فقال: «وقرأ بعض السلف -وجاء مرفوعًا-: (حَتّى إذا فُرِّغَ) بالغين المعجمة، ويرجع إلى الأول [يعني: قراءة: فُزِّع]».", "mawaqif": [{"taliq": 5327, "mi": 0, "aya": 23, "alam": "ابن جرير", "fil": "علق", "kind": "تعليق", "ref": "19/ 282", "qawl": "", "nass": "وروي عن الحسن أنه قرأ ذلك: (حتى إذا فرغ عن قلوبهم) بالراء والغين على التأويل الذي ذكرناه عن ابن زيد، وقد يحتمل توجيه معنى قراءة الحسن ذلك كذلك إلى: حتى إذا فرغ عن قلوبهم فصارت فارغة من الفزع الذي كان حل بها", "qawaid": [], "tabi": ""}, {"taliq": 5327, "mi": 0, "aya": 23, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 184", "qawl": "", "nass": "وقرأ الحسن البصري بخلاف (فزع) بضم الفاء وكسر الزاي وتخفيفها، كأنه بمعنى: أقلع، ومن قال بأنها في العالم أجمعه قال: معنى هذه القراءة: فزع الشيطان عن قلوبهم، أي: بادر. وقرأ أيوب عن الحسن أيضا (فرغ) بالفاء المضمومة والراء المشددة غير منقوطة والغين المنقوطة من التفريغ، قال أبو حاتم: رواها عن الحسن نحو من عشرة أنفس، وهي قراءة أبي مجلز. وقرأ مطر الوراق عن الحسن: (فزع) على بناء الفعل للفاعل، وهي قراءة مجاهد، وقرأ الحسن أيضا (فرغ) بالراء غير منقوطة مخففة من الفراغ، قال أبو حاتم: وما أظن الثقات رووها عن الحسن على وجوه إلا لصعوبة المعنى عليه؛ فاختلفت ألفاظه فيها", "qawaid": [], "tabi": ""}]}, {"id": 5328, "kinds": "تعليق،نقل", "text": "ذكر ابنُ جرير (19/ 282) نحو هذه القراءة عن مجاهد، وعلّق عليها، فقال: «ذكر عن مجاهد أنه قرأ ذلك: {فَزَّع} بمعنى: كشف الله الفزع عنها».\nوعلّق عليها ابنُ عطية (7/ 419)، فقال: «ومن قرأ على بناء الفعل للفاعل فقوله: {عَنْ قُلُوبِهِمْ} في موضع نصب».", "mawaqif": [{"taliq": 5328, "mi": 0, "aya": 23, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "19/ 282", "qawl": "", "nass": "ذكر عن مجاهد أنه قرأ ذلك: {فزع} بمعنى: كشف الله الفزع عنها", "qawaid": [], "tabi": ""}]}, {"id": 5329, "kinds": "تعليق", "text": "علّق ابنُ عطية (7/ 184) على هذه القراءة، فقال: «ومَن قرأ شيئًا من هذا على بناء الفعل للمفعول فقوله عز وجل: {عَنْ قُلُوبِهِمْ} في موضع رفع».", "mawaqif": [{"taliq": 5329, "mi": 0, "aya": 23, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 184", "qawl": "", "nass": "ومن قرأ شيئا من هذا على بناء الفعل للمفعول فقوله عز وجل: {عن قلوبهم} في موضع رفع", "qawaid": [], "tabi": ""}]}, {"id": 5330, "kinds": "ترجيح", "text": "رجّح ابنُ جرير (19/ 283) هذه القراءة مستندًا إلى السنة، وإجماع الحجة مِن القراء وأهل التأويل عليها، فقال: «والصواب من القراءة في ذلك القراءة بالزاي والعين؛ لإجماع الحجة من القراء وأهل التأويل عليها، ولصحة الخبر الذي ذكرناه عن رسول الله صلى الله عليه وسلم بتأييدها، والدلالة على صحتها».", "mawaqif": [{"taliq": 5330, "mi": 0, "aya": 23, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "19/ 283", "qawl": "", "nass": "والصواب من القراءة في ذلك القراءة بالزاي والعين؛ لإجماع الحجة من القراء وأهل التأويل عليها، ولصحة الخبر الذي ذكرناه عن رسول الله صلى الله عليه وسلم بتأييدها، والدلالة على صحتها", "qawaid": ["السنة", "القراءة ورسم المصحف"], "tabi": ""}]}], "27": [{"id": 5333, "kinds": "ترجيح،نقد،توجيه،نقل", "text": "ذكر ابنُ عطية (7/ 186) أن الرؤية في: {قُلْ أرُونِيَ} يحتمل: أن تكون رؤية قلب؛ فيكون قوله: {شُرَكاءَ} مفعولًا ثالثًا، ورجَّحه قائلًا: «وهذا هو الصحيح، أي: أروني بالحجة والدليل كيف وجْه الشركة». ونقل عن فرقة: بأنها رؤية بصر، و {شُرَكاءَ} حال من الضمير المفعول بـ {ألْحَقْتُمْ} والعائد على {الَّذِينَ}، ثم انتقده مستندًا إلى الدلالة العقلية قائلًا: «وهذا ضعيف؛ لأن استدعاء رؤية العين في هذا لا غناء له».", "mawaqif": [{"taliq": 5333, "mi": 0, "aya": 27, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 186", "qawl": "", "nass": "وهذا هو الصحيح، أي: أروني بالحجة والدليل كيف وجه الشركة", "qawaid": ["الدلالة العقلية"], "tabi": ""}]}], "28": [{"id": 5334, "kinds": "تعليق", "text": "علَّق ابنُ كثير (11/ 288) على القول بأنّ المرسل إليهم الجن والإنس، والقول بأنهم العرب والعجم، بقوله: «والكل صحيح».", "mawaqif": [{"taliq": 5334, "mi": 0, "aya": 28, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "11/ 288", "qawl": "بأن المرسل", "nass": "والكل صحيح", "qawaid": [], "tabi": ""}]}], "29": [{"id": 5335, "kinds": "بيان،تعليق،نقل", "text": "بيَّن ابنُ عطية (7/ 187) أنّ الآية في استعجال الكفار ليوم القيامة على سبيل الاستهزاء، ثم ذكر أنّ الآية تحتمل أن يكون استعجال الكفرة لعذاب الدنيا، ويكون الجواب عن ذلك أيضًا، ثم علَّق على ذلك بقوله: «ولم يَجْرِ للقيامة ذِكْرٌ على هذا التأويل».", "mawaqif": [{"taliq": 5335, "mi": 0, "aya": 29, "alam": "ابن عطية", "fil": "بين", "kind": "بيان", "ref": "7/ 187", "qawl": "", "nass": "ولم يجر للقيامة ذكر على هذا التأويل", "qawaid": [], "tabi": ""}]}], "31": [{"id": 5336, "kinds": "بيان", "text": "لم يذكر ابنُ جرير (19/ 289 - 290) في معنى: {وقالَ الَّذِينَ كَفَرُوا لَنْ نُؤْمِنَ بِهَذا القُرْآنِ ولا بِالَّذِي بَيْنَ يَدَيْهِ} سوى قول قتادة.", "mawaqif": []}, {"id": 5337, "kinds": "نقد،بيان،نقل", "text": "نقل ابنُ عطية (7/ 188) عن فرقة أن «الذي بين يديه»: هي الساعة والقيامة. ثم انتقد ذلك مستندًا إلى اللغة قائلًا: «وهذا خطأٌ لم يفهَم قائله أمر» بَيْنَ اليد «في اللغة، وأنه المتقدم في الزمن».", "mawaqif": [{"taliq": 5337, "mi": 0, "aya": 31, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "7/ 188", "qawl": "", "nass": "الذي بين يديه»: هي الساعة والقيامة. ثم انتقد ذلك مستندا إلى اللغة قائلا: «وهذا خطأ لم يفهم قائله أمر", "qawaid": ["اللغة"], "tabi": ""}]}], "33": [{"id": 5338, "kinds": "تعليق،نقل", "text": "لم يذكر ابنُ جرير (19/ 292 - 293) في معنى: {وأَسَرُّوا النَّدامَةَ لَمّا رَأَوُا العَذابَ} سوى قول قتادة.\nونقل ابنُ عطية (7/ 189) عن بعض الناس أن {وأَسَرُّوا} بمعنى: «أظهروا، وهي من الأضداد». ثم علَّق بقوله: «وهذا كلام مَن لم يعتبر المعنى، أمّا نفس الندامة فلا تكون إلا مُسْتَسَرَّة ضرورة، وأما الظاهر عنها فغيرها، ولم يثبت قط في لغة أن» أسَرَّ «من الأضداد».", "mawaqif": [{"taliq": 5338, "mi": 0, "aya": 33, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "7/ 189", "qawl": "", "nass": "أظهروا، وهي من الأضداد", "qawaid": [], "tabi": ""}]}], "35": [{"id": 5339, "kinds": "نقد،نقل", "text": "ذكر ابنُ عطية (7/ 189) احتمالًا آخر، فقال: «يحتمل أن يكون الضمير في {قالوا} لقريش، ويكون كلام المترفين قد تقدم، ثم تطَّرد الآية بعد». وذكر أن معنى: {نَحْنُ أكْثَرُ أمْوالا وأَوْلادًا وما نَحْنُ بِمُعَذَّبِينَ}: «الاحتجاج بأن الله لم يُعْطِنا هذا وقدَّره لنا إلا لرضاه عنّا وعن طريقتنا، ونحن ممن لا يُعَذَّب البَتَّة؛ إذ الله -الذي تزعم أنت علمَه بجميع الأشياء وإحاطته- قد قدَّر علينا النِّعم، فهو إذًا راضٍ عنّا». ثم ذكر عن بعض المفسرين أن معنى: {وما نَحْنُ بِمُعَذَّبِينَ} أي: بالفقر، وانتقده قائلًا: «وهذا ليس كالأول في القوة».", "mawaqif": [{"taliq": 5339, "mi": 0, "aya": 35, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 189", "qawl": "", "nass": "يحتمل أن يكون الضمير في {قالوا} لقريش، ويكون كلام المترفين قد تقدم، ثم تطرد الآية بعد", "qawaid": [], "tabi": ""}]}], "37": [{"id": 5340, "kinds": "توجيه،نقل", "text": "نقل ابنُ جرير (19/ 297) عن بعضهم أنّ معنى قوله تعالى: {وما أمْوالُكُمْ ولا أوْلادَكُمْ بِالَّتِي تُقَرِّبُكُمْ عِنْدَنا زُلْفى إلا مَن آمَنَ وعَمِلَ صالِحًا}: «وما أموالكم ولا أولادكم بالتي تقرِّبكم عندنا زُلفى، إلا من آمن وعمل صالحًا، فإنه تُقَرِّبهم أموالهم وأولادهم -بطاعتهم الله في ذلك، وأدائهم فيه حقَّه إلى الله- زُلفى، دون أهل الكفر بالله». وذكر قول ابن زيد، ثم وجَّه هذا المعنى بقوله: «فـ {من} على هذا التأويل نصبٌ بوقوع» تقرب «عليه».", "mawaqif": [{"taliq": 5340, "mi": 0, "aya": 37, "alam": "ابن جرير", "fil": "نقل", "kind": "نقل", "ref": "19/ 297", "qawl": "", "nass": "وما أموالكم ولا أولادكم بالتي تقربكم عندنا زلفى، إلا من آمن وعمل صالحا، فإنه تقربهم أموالهم وأولادهم -بطاعتهم الله في ذلك، وأدائهم فيه حقه إلى الله- زلفى، دون أهل الكفر بالله", "qawaid": [], "tabi": ""}]}], "39": [{"id": 5341, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (19/ 299) في معنى: {وما أنْفَقْتُمْ مِن شَيْءٍ فَهُوَ يُخْلِفُهُ} سوى قول سعيد بن جبير، من طريق المنهال بن عمرو.", "mawaqif": []}], "45": [{"id": 5342, "kinds": "تعليق", "text": "لم يذكر ابنُ جرير (19/ 303) في معنى: {وما بَلَغُوا مِعْشارَ ما آتَيْناهُمْ} سوى قول ابن عباس، وقتادة، وابن زيد.\nوعلَّق ابنُ كثير (11/ 295) عليها بقوله: «كما قال تعالى: {ولَقَدْ مَكَّنّاهُمْ فِيما إنْ مَكَّنّاكُمْ فِيهِ وجَعَلْنا لَهُمْ سَمْعًا وأَبْصارًا وأَفْئِدَةً فَما أغْنى عَنْهُمْ سَمْعُهُمْ ولا أبْصارُهُمْ ولا أفْئِدَتُهُمْ مِن شَيْءٍ إذْ كانُوا يَجْحَدُونَ بِآياتِ اللَّهِ وحاقَ بِهِمْ ما كانُوا بِهِ يَسْتَهْزِئُونَ} [الأحقاف: 26]، {أفَلَمْ يَسِيرُوا فِي الأرْضِ فَيَنْظُرُوا كَيْفَ كانَ عاقِبَةُ الَّذِينَ مِن قَبْلِهِمْ كانُوا أكْثَرَ مِنهُمْ وأَشَدَّ قُوَّةً} [غافر: 82] أي: وما دفع ذلك عنهم عذاب الله ولا ردَّه، بل دمَّر الله عليهم لما كذَّبوا رسله».", "mawaqif": [{"taliq": 5342, "mi": 0, "aya": 45, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "11/ 295", "qawl": "", "nass": "كما قال تعالى: {ولقد مكناهم فيما إن مكناكم فيه وجعلنا لهم سمعا وأبصارا وأفئدة فما أغنى عنهم سمعهم ولا أبصارهم ولا أفئدتهم من شيء إذ كانوا يجحدون بآيات الله وحاق بهم ما كانوا به يستهزئون} [الأحقاف: 26]، {أفلم يسيروا في الأرض فينظروا كيف كان عاقبة الذين من قبلهم كانوا أكثر منهم وأشد قوة} [غافر: 82] أي: وما دفع ذلك عنهم عذاب الله ولا رده، بل دمر الله عليهم لما كذبوا رسله", "qawaid": [], "tabi": ""}]}], "46": [{"id": 5344, "kinds": "نقد،نقل", "text": "ذكر ابن كثير (11/ 296) هذا الحديث من رواية ابن أبي حاتم بسنده عن أبيه، عن هشام بن عمار، عن صدقة بن خالد، عن عثمان بن أبي العاتكة، عن علي بن يزيد، عن القاسم، عن أبي أمامة مرفوعًا، ثم استدرك بأنه: «حديث ضعيف الإسناد، وتفسير الآية بالقيام في الصلاة في جماعة وفرادى؛ بعيد، ولعله مقحم في الحديث مِن بعض الرواة؛ فإنّ أصله ثابت في الصحاح وغيرها».", "mawaqif": [{"taliq": 5344, "mi": 0, "aya": 46, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "11/ 296", "qawl": "", "nass": "حديث ضعيف الإسناد، وتفسير الآية بالقيام في الصلاة في جماعة وفرادى؛ بعيد، ولعله مقحم في الحديث من بعض الرواة؛ فإن أصله ثابت في الصحاح وغيرها", "qawaid": [], "tabi": ""}]}, {"id": 5345, "kinds": "ترجيح،نقل", "text": "ذكر ابنُ كثير (11/ 296) معنى قول مجاهد، وقتادة، ومحمد بن كعب، والسدي، ثم رجَّحه قائلًا: «وهذا هو المراد من الآية» ولم يذكر مستندًا.", "mawaqif": [{"taliq": 5345, "mi": 0, "aya": 46, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "11/ 296", "qawl": "مجاهد", "nass": "وهذا هو المراد من الآية", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}]}], "49": [{"id": 5347, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (19/ 307) في معنى: {قُلْ جاءَ الحَقُّ} سوى قول قتادة.", "mawaqif": []}, {"id": 5348, "kinds": "نقد،توجيه،نقل", "text": "نقل ابنُ عطية (7/ 195) عن فرقة أن الباطل: الشيطان. ووجَّه هذا المعنى بقوله: «والمعنى: وما يفعل الباطل شيئًا مفيدًا، أي: ليس يخلق ولا يرزق».\nوذكر ابنُ كثير (11/ 298) قول قتادة، ثم انتقده قائلًا: «وهذا وإن كان حقًّا، ولكن ليس هو المراد هاهنا».", "mawaqif": [{"taliq": 5348, "mi": 0, "aya": 49, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "7/ 195", "qawl": "", "nass": "والمعنى: وما يفعل الباطل شيئا مفيدا، أي: ليس يخلق ولا يرزق", "qawaid": [], "tabi": ""}, {"taliq": 5348, "mi": 0, "aya": 49, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "11/ 298", "qawl": "قتادة", "nass": "وهذا وإن كان حقا، ولكن ليس هو المراد هاهنا", "qawaid": [], "tabi": ""}]}], "51": [{"id": 5349, "kinds": "توجيه،تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 196) أنّ قوله تعالى: {وأُخِذُوا مِن مَكانٍ قَرِيبٍ} «معناه: أنهم للقدرة قريب حيث كانوا». ثم ذكر قول مجاهد من طريق ابن جريج، ووجَّهه بقوله: «وهذا يتوجَّه على بعض الأقوال». ثم علَّق بقوله: «والذي يعُمُّ جميعها أن يقال: إن الأخذ يجيئهم مِن قرب في طمأنينتهم، بينا الكافر يؤمِّل ويَظُنُّ ويترجّى إذ غشيه الأخذ، ومن غشيه أُخذ من قريب، فلا حيلة له ولا رويَّة».", "mawaqif": [{"taliq": 5349, "mi": 0, "aya": 51, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 196", "qawl": "", "nass": "معناه: أنهم للقدرة قريب حيث كانوا", "qawaid": [], "tabi": ""}]}], "52": [{"id": 5352, "kinds": "نقل", "text": "نقل ابنُ عطية (7/ 197) قولًا أن الضمير في {به} عائد على محمد صلى الله عليه وسلم وشرعه والقرآن.", "mawaqif": [{"taliq": 5352, "mi": 0, "aya": 52, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "7/ 197", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}]}, {"id": 5353, "kinds": "توجيه،نقل", "text": "ذكر ابنُ عطية (7/ 198) قولًا عن ابن عباس -حكاه عنه ابن الأنباري- أن معنى تَناوُش الشيء: رجوعه، ثم وجَّهه بقوله: «وكأنه قال في الآية: وأنّى لهم طلب مرادهم وقد بَعُد».", "mawaqif": [{"taliq": 5353, "mi": 0, "aya": 52, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 198", "qawl": "", "nass": "وكأنه قال في الآية: وأنى لهم طلب مرادهم وقد بعد", "qawaid": [], "tabi": ""}]}], "53": [{"id": 5354, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (19/ 320) في معنى: {ويَقْذِفُونَ بِالغَيْبِ مِن مَكانٍ بَعِيدٍ} سوى قول مجاهد، وقتادة، وابن زيد.", "mawaqif": []}], "54": [{"id": 5356, "kinds": "نقد،بيان", "text": "انتقد ابنُ كثير (11/ 302) هذا الأثر، فقال: «هذا أثر غريب، وفي صحته نظر، وتنزيل الآية عليه وفي حقه بمعنى: أنّ الكفار كلهم يتوفون وأرواحهم متعلقة بالحياة الدنيا، كما جرى لهذا المغرور المفتون، ذهب يطلب مراده فجاءه الموت فجأة بغتة، وحيل بينه وبين ما يشتهي».", "mawaqif": [{"taliq": 5356, "mi": 0, "aya": 54, "alam": "ابن كثير", "fil": "انتقد", "kind": "نقد", "ref": "11/ 302", "qawl": "", "nass": "هذا أثر غريب، وفي صحته نظر، وتنزيل الآية عليه وفي حقه بمعنى: أن الكفار كلهم يتوفون وأرواحهم متعلقة بالحياة الدنيا، كما جرى لهذا المغرور المفتون، ذهب يطلب مراده فجاءه الموت فجأة بغتة، وحيل بينه وبين ما يشتهي", "qawaid": [], "tabi": ""}]}]}, "athar": {"63110": {"num": 63110, "aya": 11, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {أنِ اعْمَلْ سابِغاتٍ}: دروع، وكان داود أوَّل مَن صنعها، وإنما كانت قبل ذلك صفائحَ مِن حديد، يجتنُّون بها مِن عدوهم."}, "63111": {"num": 63111, "aya": 11, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- في قوله: {أنِ اعْمَلْ سابِغاتٍ}، قال: دروع سابغات."}, "63113": {"num": 63113, "aya": 11, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {أنِ اعْمَلْ سابِغاتٍ}، قال: السابغات: دروع الحديد."}, "63114": {"num": 63114, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق مجاهد- في قوله: {وقَدِّرْ فِي السَّرْدِ}، قال: لا تُدِقّ المسامير وتوسِّع الحِلق فتسْلس، ولا تغلِّظ المسامير وتُضيِّق الحِلق فتنقصم، واجعله قدرًا."}, "63115": {"num": 63115, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {وقَدِّرْ فِي السَّرْدِ}، قال: حِلَق الحديد."}, "63116": {"num": 63116, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العوفي-: {وقَدِّرْ فِي السَّرْدِ} يعني بالسرد: ثقْب الدروع حين يشُدُّ قَتيرَها، وعنى بقوله: {وقَدِّرْ فِي السَّرْدِ}: قدِّر المسامير."}, "63117": {"num": 63117, "aya": 11, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {وقَدِّرْ فِي السَّرْدِ}، قال: قدِّر المسامير والحِلق؛ لا تُدق المسمار فتسْلَس، ولا تُجلّها فتُقْصَم."}, "63118": {"num": 63118, "aya": 11, "qail": "الحكم بن عتيبة", "tabaqa": "تابعي", "bab": "", "text": "عن الحكم [بن عتيبة]-من طريق عيينة- {وقَدِّرْ فِي السَّرْدِ}، قال: لا تغلِّظ المسمار فيفصم الحلقة، ولا تدقّه فيقلق."}, "63119": {"num": 63119, "aya": 11, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- في قوله: {وقَدِّرْ فِي السَّرْدِ}، قال: السرد: هي المسامير التي في حِلق الدرع."}, "63120": {"num": 63120, "aya": 11, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {وقَدِّرْ فِي السَّرْدِ}، قال: كان يجعلها بغير نار، ولا يقرعها بحديد، ثم يسردها. والسرد: المسامير التي في الحِلق."}, "63121": {"num": 63121, "aya": 11, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق خالد بن قيس- {وقَدِّرْ فِي السَّرْدِ}، قال: كانت صفائح، فأمر أن يَسْرُدَها حِلَقًا."}, "63634": {"num": 63634, "aya": 46, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {قُلْ إنَّما أعِظُكُمْ بِواحِدَةٍ}، قال: بطاعة الله."}, "63123": {"num": 63123, "aya": 11, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {وقَدِّرْ فِي السَّرْدِ}، قال: السرد: حلقة، أي: قدِّر تلك الحِلَق. قال: وقال الشاعر: أجاد المُسدِّي سَرْدَها وأذالها قال: يقول: وسَّعها، وأجاد حلَقها."}, "63635": {"num": 63635, "aya": 46, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر، {أعِظُكُمْ بِواحِدَةٍ}، قال: بلا إله إلا الله."}, "63636": {"num": 63636, "aya": 46, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- في قوله تعالى: {قُلْ إنَّما أعِظُكُمْ بِواحِدَةٍ} يقول: بواحدة، {أنْ تَقُومُوا لِلَّهِ مَثْنى وفُرادى} فهذه واحدة وعَظَهُم بها."}, "63642": {"num": 63642, "aya": 46, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {أنْ تَقُومُوا لِلَّهِ مَثْنى وفُرادى}، قال: واحد واثنين."}, "63643": {"num": 63643, "aya": 46, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {قُلْ إنَّما أعِظُكُمْ بِواحِدَةٍ أنْ تَقُومُوا لِلَّهِ مَثْنى وفُرادى}، قال: هذه الواحدة التي وعظتُكم بها؛ أن تقوموا لله رجلًا ورجلين."}, "63648": {"num": 63648, "aya": 46, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {ما بِصاحِبِكُمْ مِن جِنَّةٍ}، يقول: إنّه ليس بمجنون."}, "63677": {"num": 63677, "aya": 51, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "نزول الآية", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- {ولَوْ تَرى إذْ فَزِعُوا فَلا فَوْتَ}، قال: هؤلاء قتلى المشركين من أهل بدر، نزلت فيهم هذه الآية. قال: وهم الذين بدَّلوا نعمة الله كفرًا، وأحلَّوا قومهم دار البوار جهنم، أهل بدر من المشركين."}, "63681": {"num": 63681, "aya": 51, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {فَلا فَوْتَ}، قال: فلا نجاة."}, "63682": {"num": 63682, "aya": 51, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس، أنّه سُئِل عن قوله: {ولَوْ تَرى إذْ فَزِعُوا فَلا فَوْتَ وأُخِذُوا مِن مَكانٍ قَرِيبٍ}. قال: هو جيش السفياني. قيل: مِن أين أُخِذُوا؟ قال: من تحت أقدامهم."}, "63683": {"num": 63683, "aya": 51, "qail": "ابن معقل", "tabaqa": "", "bab": "تفسير الآية", "text": "عن ابن مَعْقل -من طريق عطاء بن السائب- {ولَوْ تَرى إذْ فَزِعُوا فَلا فَوْتَ}، قال: أفزعهم فلم يفوتوه."}, "63684": {"num": 63684, "aya": 51, "qail": "سعيد بن المسيب", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن سعيد بن المسيب -من طريق جعفر- في قوله: {ولَوْ تَرى إذْ فَزِعُوا فَلا فَوْتَ}، قال: هم الجيش الذي يُخسَف بهم بالبيداء، يبقى منهم رجل يُخْبِرُ الناسَ بما لقي أصحابُه."}, "63687": {"num": 63687, "aya": 51, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الضحاك بن مزاحم، {ولَوْ تَرى إذْ فَزِعُوا فَلا فَوْتَ}، قال: هو يوم بدر."}, "63689": {"num": 63689, "aya": 51, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الضحاك بن مُزاحِم -من طريق جُوَيْبِر- في قوله: {ولَوْ تَرى إذْ فَزِعُوا فَلا فَوْتَ}، قال: لا هَرَبَ."}, "63690": {"num": 63690, "aya": 51, "qail": "الضحاك بن مزاحم", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الضحاك بن مُزاحِم -من طريق عبيد- في قوله: {وأُخِذُوا مِن مَكانٍ قَرِيبٍ}، قال: هذا عذاب الدُّنيا."}, "63691": {"num": 63691, "aya": 51, "qail": "سعيد بن عبد الرحمن بن أبزى", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن سعيد بن عبد الرحمن بن أبزى -من طريق جعفر بن أبي المغيرة- {ولَوْ تَرى إذْ فَزِعُوا فَلا فَوْتَ}، قال: خُسِف بالبيداء."}, "63692": {"num": 63692, "aya": 51, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق قتادة- في قوله: {ولَوْ تَرى إذْ فَزِعُوا}، قال: فزعوا يوم القيامة حين خرجوا مِن قبورهم."}, "63693": {"num": 63693, "aya": 51, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق عمرو-: {ولَوْ تَرى إذْ فَزِعُوا}، يعني: النفخة الأولى التي يُهلِك اللهُ بها كفارَ آخرِ هذه الأمة."}, "63694": {"num": 63694, "aya": 51, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "قال الحسن البصري، في قوله: {وأُخِذُوا مِن مَكانٍ قَرِيبٍ}: وأيُّ شيءٍ أقربُ مِن أن كانوا في بطن الأرض فإذا هم على ظهرها!."}, "63734": {"num": 63734, "aya": 54, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق عيسى وورقاء، عن ابن أبي نجيح- في قوله: {وحِيلَ بَيْنَهُمْ وبَيْنَ ما يَشْتَهُونَ}، قال: مِن مال، أو ولد، أو زهرة، أو أهل."}, "63735": {"num": 63735, "aya": 54, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق شبل، عن ابن أبي نجيح- {وحِيلَ بَيْنَهُمْ وبَيْنَ ما يَشْتَهُونَ}، قال: مِن الرجوع إلى الدنيا؛ ليتوبوا."}, "63736": {"num": 63736, "aya": 54, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق أبي الأشهب- في قوله: {وحِيلَ بَيْنَهُمْ وبَيْنَ ما يَشْتَهُونَ}، قال: حيل بينهم وبين الإيمان."}, "63738": {"num": 63738, "aya": 54, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {وحِيلَ بَيْنَهُمْ وبَيْنَ ما يَشْتَهُونَ}: كان القوم يشتهون طاعةَ الله أن يكونوا عمِلوا بها في الدنيا حين عاينوا ما عاينوا."}, "63741": {"num": 63741, "aya": 54, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {وحِيلَ بَيْنَهُمْ وبَيْنَ ما يَشْتَهُونَ}، قال: الدنيا التي كانوا فيها والحياة."}, "63745": {"num": 63745, "aya": 54, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر، في قوله: {كَما فُعِلَ بِأَشْياعِهِمْ مِن قَبْلُ}، قال: أي: مِن الكفار من قبلهم؛ كما فُعل بأمثالهم."}, "63746": {"num": 63746, "aya": 54, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {كَما فُعِلَ بِأَشْياعِهِمْ مِن قَبْلُ}: أي: في الدنيا، كانوا إذا عاينوا العذاب لم يقبل منهم إيمان."}, "63751": {"num": 63751, "aya": 54, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة، في قوله: {إنَّهُمْ كانُوا فِي شَكٍّ مُرِيبٍ}، قال: إيّاكم والشكَّ والريبةَ؛ فإنّه مَن مات على شكٍّ بُعث عليه، ومَن مات على يقين بُعِث عليه."}, "63284": {"num": 63284, "aya": 16, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة، في قوله: {فَأَعْرَضُوا}، قال: بطِر القومُ أمرَ الله، وكفروا نعمته."}, "63286": {"num": 63286, "aya": 16, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العوفي- {فَأَرْسَلْنا عَلَيْهِمْ سَيْلَ العَرِمِ}، قال: بعث اللهُ عليهم -يعني: على العَرِم- دابَّةً مِن الأرض، فنقَبتْ فيه نقبًا، فسال ذلك الماءُ إلى موضع غير الموضع الذي كانوا ينتفعون به، وأبدلهم الله مكان جنتيهم جنتين ذواتي أكل خَمْط وأَثْل، وذلك حين عصوا، وبطروا المعيشة."}, "63287": {"num": 63287, "aya": 16, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "قال عبد الله بن عباس ="}, "63290": {"num": 63290, "aya": 16, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {سَيْلَ العَرِمِ}، قال: العَرم: السد؛ ماء أحمر أرسله الله في السد، فبَثَقه وهدمه، وحفر الوادي عن الجنتين، فارتفعتا، وغار عنهما الماء، فيَبِسَتا، ولم يكن الماءُ الأحمرُ مِن السد، كان شيئًا أرسله الله عليهم."}, "63295": {"num": 63295, "aya": 16, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {فَأَعْرَضُوا}، قال: ترك القومُ أمرَ الله {فَأَرْسَلْنا عَلَيْهِمْ سَيْلَ العَرِمِ}. ذُكِر لنا: أنّ العِرم وادي سبأ، كانت تجتمع إليه مسايل من أودية شتّى، فعمدوا فسدُّوا ما بين الجبلين بالقير والحجارة، وجعلوا عليه أبوابًا، وكانوا يأخذون من مائه ما احتاجوا إليه، ويسدُّون عنهم ما لَمْ يُعْنَوا بِهِ مِن مائه، فلمّا تركوا أمر الله بعث الله عليهم جُرذًا، فنقبه من أسفله، فاتسع حتى غرَّق الله به حروثَهم، وخرَّب به أراضيهم؛ عقوبةً بأعمالهم."}, "63298": {"num": 63298, "aya": 16, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب-: بعث الله عليهم جرذًا، وسلَّطه على الذي كان يحبس الماء الذي يسقيهما، فأخرب في أجواف تلك الحجارة، وكل شيء منها من رصاص وغيره، حتى تركها حجارة، ثم بعث الله سيل العرم، فاقتلع ذلك السد وما كان يحبس، واقتلع تلك الجنتين، فذهب بهما. وقرأ: {فَأَرْسَلْنا عَلَيْهِمْ سَيْلَ العَرِمِ وبَدَّلْناهُمْ بِجَنَّتَيْهِمْ جَنَّتَيْنِ}، قال: ذهب بتلك القرى والجنتين. (ز)  {سَيْلَ الْعَرِمِ}"}, "63299": {"num": 63299, "aya": 16, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {سَيْلَ العَرِمِ}، قال: الشديد."}, "63300": {"num": 63300, "aya": 16, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العوفي- {سَيْلَ العَرِمِ}، قال: وادٍ كان باليمن، كان يَسِيلُ إلى مكة."}, "63302": {"num": 63302, "aya": 16, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر، في قوله: {سَيْلَ العَرِمِ}، قال: العرم بالحبشية؛ وهي المُسَنّاة التي يجتمع فيها الماء ثم ينبثق."}, "63303": {"num": 63303, "aya": 16, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قول الله: {سَيْلَ العَرِمِ}، قال: سَدٌّ."}, "63309": {"num": 63309, "aya": 16, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {أُكُلٍ خَمْطٍ}، قال: الخمْط: الأراك."}, "63310": {"num": 63310, "aya": 16, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس: أنّ نافع بن الأزرق قال له: أخبِرني عن قوله: {أُكُلٍ خَمْطٍ}. قال: الأراك. قال: وهل تعرف العربُ ذلك؟ قال: نعم، أما سمعت الشاعر وهو يقول: وما مُغزِلٌ فَرْدٌ تُراعي بعينها … أغَنَّ غَضِيضَ الطرْفِ من خَلل الخمْط."}, "63311": {"num": 63311, "aya": 16, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق أبي يحيى- في قوله: {أُكُلٍ خَمْطٍ}، قال: الخمْط: الأراك."}, "63318": {"num": 63318, "aya": 16, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {وبَدَّلْناهُمْ بِجَنَّتَيْهِمْ جَنَّتَيْنِ ذَواتَيْ أُكُلٍ خَمْطٍ}: والخمْط: الأراك. وأُكُلُهُ: بَرِيرُهُ."}, "63322": {"num": 63322, "aya": 16, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {وبَدَّلْناهُمْ بِجَنَّتَيْهِمْ جَنَّتَيْنِ}، قال: ذهب بتلك القرى والجنتين، وأبدلهم الذي أخبرك ذواتي أكل خمْط. قال: والخمط: الأراك. قال: جعل مكان العنب أراكًا، والفاكهة أثْلًا، وبقي لهم شيء مِن سِدر قليل."}, "63326": {"num": 63326, "aya": 16, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {وأَثْلٍ}، قال: الطَّرْفاء."}, "63330": {"num": 63330, "aya": 16, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {وأَثْلٍ وشَيْءٍ مِن سِدْرٍ قَلِيلٍ}: بينما شجر القوم مِن خير الشجر إذ صيّره الله مِن شرِّ الشجر؛ عقوبة بأعمالهم."}, "63434": {"num": 63434, "aya": 23, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "قراءات الآية، وتفسيرها", "text": "عن عبد الله بن مسعود -من طريق مسروق- {حَتّى إذا فُزِّعَ عَنْ قُلُوبِهِمْ}، قال: رُفِّه عن قلوبهم."}, "63435": {"num": 63435, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "قراءات الآية، وتفسيرها", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {فُزِّعَ عَنْ قُلُوبِهِمْ}، قال: جُلِّي."}, "63437": {"num": 63437, "aya": 23, "qail": "عبد الله بن عمر", "tabaqa": "صحابي", "bab": "قراءات الآية، وتفسيرها", "text": "عن عبد الله بن عمر -من طريق نافع- كان يقول: {حتى إذا فزع عن قلوبهم}، قال: جُلِّيَ عن قلوب القوم."}, "63438": {"num": 63438, "aya": 23, "qail": "مسروق بن الأجدع الهمداني", "tabaqa": "تابعي", "bab": "قراءات الآية، وتفسيرها", "text": "عن مسروق بن الأجدع الهمداني -من طريق أبي وائل- أنه كان يقرؤها: (حَتىَّ إذا فُزِعَ عَن قُلُوبِهِمْ)."}, "63439": {"num": 63439, "aya": 23, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "قراءات الآية، وتفسيرها", "text": "عن سعيد بن جبير -من طريق عطاء بن السائب-، مثله."}, "63440": {"num": 63440, "aya": 23, "qail": "عبد الله بن شداد بن الهاد", "tabaqa": "تابعي", "bab": "قراءات الآية، وتفسيرها", "text": "عن عبد الله بن شداد بن الهاد -من طريق يزيد بن أبي زياد- في قوله: {حتى إذا فزع عن قلوبهم}: ذهب الرَّوْعُ عنهم."}, "63450": {"num": 63450, "aya": 23, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "قراءات الآية، وتفسيرها", "text": "عن قتادة بن دعامة، أنّه قرأ: (حَتّى إذا فَزَّعَ عَن قُلُوبِهِمْ)."}, "63451": {"num": 63451, "aya": 23, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "قراءات الآية، وتفسيرها", "text": "عن قتادة بن دعامة -من طريق معمر- ="}, "63457": {"num": 63457, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، قال: أخبَرني رجلٌ مِن أصحاب النبي صلى الله عليه وسلم من الأنصار: أنّهم بينما هم جلوسٌ ليلةً مع رسول الله صلى الله عليه وسلم رُمِي بنجم، فاستنار، فقال لهم رسول الله صلى الله عليه وسلم: «ماذا كنتم تقولون في الجاهلية إذا رُمِي بمثل هذا؟». قالوا: الله ورسوله أعلم، كُنّا نقول: وُلد الليلةَ رجلٌ عظيم، ومات رجلٌ عظيم. فقال رسول الله صلى الله عليه وسلم: «فإنّها لا يُرمى بها لموت أحد ولا لحياته، ولكن ربنا تبارك وتعالى اسمه- إذا قضى أمرًا سبَّح حملة العرش، ثم سبَّح أهل السماء الذين يلونهم، حتى يبلغ التسبيح أهل هذه السماء الدنيا، فيقول الذين يلون حملة العرش لحملة العرش: {ماذا قالَ رَبُّكُمْ}؟ فيخبرونهم ماذا قال». قال: «فيستخبر بعض أهل السماوات بعضًا، حتى يبلغ الخبر هذه السماء الدنيا، فتخطف الجن السمع، فيقذفون إلى أوليائهم، ويرمون به، فما جاءوا به على وجهه فهو حقٌّ، ولكنهم يقرفون فيه ويزيدون»."}, "63459": {"num": 63459, "aya": 23, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود، قال: قال رسول الله صلى الله عليه وسلم: «إذا تكلّم الله بالوحي سمع أهلُ السماء الدنيا صلصلةً كجرِّ السلسلة على الصفا، فيَصْعقون، فلا يزالون كذلك حتى يأتيهم جبريل، حتى إذا جاءهم جبريل فُزِّع عن قلوبهم، فيقولون: يا جبريل، ماذا قال ربك؟ فيقول: الحق. فيقولون: الحق الحق»."}, "63460": {"num": 63460, "aya": 23, "qail": "النواس بن سمعان", "tabaqa": "", "bab": "", "text": "عن النواس بن سمعان، قال: قال رسول الله صلى الله عليه وسلم: «إذا أراد اللهُ أن يوحي بأمر تكلّم بالوحي، فإذا تكلّم بالوحي أخذت السماوات رجفةٌ شديدة مِن خوف الله، فإذا سمع بذلك أهلُ السموات صَعقوا، وخرّوا سُجّدًا، فيكون أول مَن يرفع رأسه جبريل، فيكلّمه الله مِن وحيه بما أراد، فيمضي به جبريلُ على الملائكة، كلمّا مرَّ بسماء سماء سأله ملائكتُها: ماذا قال ربُّنا، يا جبريل؟ فيقول: قال الحق، وهو العلي الكبير. فيقولون كلهم مثل ما قال جبريل، فينتهي جبريل بالوحي حيث أمره الله مِن السماء والأرض»."}, "63462": {"num": 63462, "aya": 23, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق الضحاك- {حَتّى إذا فُزِّعَ عَن قُلُوبِهِمْ قالُوا ماذا قالَ رَبُّكُمْ قالُوا الحَقَّ وهُوَ العَلِيُّ الكَبِيرُ}، قال: إنّ الملائكة المُعقِّبات -الذين يختلفون إلى أهل الأرض يكتبون أعمالهم- إذا أرسلهم الربُّ تبارك وتعالى فانحدروا سُمِع لهم صوتٌ شديد، فيحسب الذين هم أسفل منهم من الملائكة أنّه مِن أمر الساعة، فيخرّون سجدًا، وهكذا كُلَّما مرّوا عليهم؛ فيفعلون ذلك من خوف ربهم تبارك وتعالى."}, "63463": {"num": 63463, "aya": 23, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق إبراهيم- قال: {حَتّى إذا فُزِّعَ عَن قُلُوبِهِمْ قالُوا ماذا قالَ رَبُّكُمْ قالُوا الحَقَّ وهُوَ العَلِيُّ الكَبِيرُ}، إذا تكلم الله بالوحي سمع أهل السموات صلْصلة كجرِّ السلسلة على الصفوان، فيصْعقون، فلا يزالون كذلك حتى يأتيهم جبريل، فإذا أتاهم جبريل فُزِّع عن قلوبهم، قالوا: يا جبريل، ماذا قال ربنا؟ فيقول: الحق. فينادون: الحق الحق."}, "63464": {"num": 63464, "aya": 23, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله [بن مسعود]-من طريق مسروق-، نحوه."}, "63465": {"num": 63465, "aya": 23, "qail": "عبد الله بن مسعود", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن مسعود -من طريق الشعبي- قال في قوله: {حَتّى إذا فُزِّعَ عَنْ قُلُوبِهِمْ}، قال: إذا حدث أمرٌ عند ذي العرش سَمِع مَن دونه مِن الملائكة صوتًا كجرِّ السلسلة على الصفا، فيُغشى عليهم، فإذا ذهب الفزع عن قلوبهم تنادوا: {ماذا قالَ رَبُّكُمْ}. قال: فيقول مَن شاء: {قال الحق، وهو العلي الكبير}."}, "63466": {"num": 63466, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق العوفي- قال: لَمّا أوحى الجبّارُ إلى محمد صلى الله عليه وسلم دعا الرسولَ مِن الملائكة ليبعثه بالوحي، فسمعتِ الملائكةُ صوت الجبار يتكلم بالوحي، فلما كُشف عن قلوبهم سألوا عمّا قال الله، فقالوا: الحق. وعلموا أنّ الله لا يقول إلا حقًّا. قال ابن عباس: وصوت الوحي كصوت الحديد على الصفا. فلما سَمِعُوا خرُّوا سُجَّدًا، فلما رفعوا رؤوسهم {قالُوا ماذا قالَ رَبُّكُمْ قالُوا الحَقَّ وهُوَ العَلِيُّ الكَبِيرُ}."}, "63467": {"num": 63467, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق الضحاك- يقول في قوله: {حَتّى إذا فُزِّعَ عَنْ قُلُوبِهِمْ} الآية: إنّ الله لَمّا أراد أن يوحي إلى محمد دعا جبريل، فلمّا تكلم ربُّنا بالوحي كان صوته كصوت الحديد على الصفا، فلما سمع أهل السموات صوت الحديد خرُّوا سجدًا، فلما أتى عليهم جبرائيل بالرسالة رفعوا رءوسهم، فقالوا: {ماذا قالَ رَبُّكُمْ قالُوا الحَقَّ وهُوَ العَلِيُّ الكَبِيرُ}. وهذا قول الملائكة."}, "63468": {"num": 63468, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، قال: كان إذا نزل الوحي كان صوته كوقْع الحديد على الصفوان، فيصْعق أهل السماء، {حَتّى إذا فُزِّعَ عَنْ قُلُوبِهِمْ قالُوا ماذا قالَ رَبُّكُمْ}؟ قالت الرسل: {الحَقَّ وهُوَ العَلِيُّ الكَبِيرُ}."}, "63469": {"num": 63469, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، قال: ينزل الأمرُ إلى السماء الدنيا له وقْعٌ كوقعة السلسلة على الصخرة، فيَفْزع له جميعُ أهل السماوات، فيقولون: {ماذا قالَ رَبُّكُمْ}؟ ثم يرجعون إلى أنفسهم فيقولون: {الحَقَّ وهُوَ العَلِيُّ الكَبِيرُ}."}, "63470": {"num": 63470, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق سعيد بن جبير- في قوله عز وجل: {حَتّى إذا فُزِّعَ عَنْ قُلُوبِهِمْ}، قال: كان لكلِّ قَبيلٍ مِن الجن مقعد مِن السماء يستمعون منه الوحي، وكان إذا نزل الوحيُ سُمِع له صوت كإمرار السلسلة على الصفوان، فلا ينزل على أهل سماء إلا صَعقوا، {حَتّى إذا فُزِّعَ عَنْ قُلُوبِهِمْ قالُوا ماذا قالَ رَبُّكُمْ قالُوا الحَقَّ وهُوَ العَلِيُّ الكَبِيرُ} وإن كان مما يكون في الأرض من أمر غيبٍ أو موت أو شيء مما يكون في الأرض تكلّموا به، فقالوا: يكون كذا، وكذا. فسمعته الشياطين، فنزلوا به على أوليائهم، يقولون: يكون العام كذا، ويكون كذا. فيسمعه الجن، فيخبرون الكهنة به، والكهنة تخبر به الناس: يكون كذا وكذا. فيجدونه كذلك، فلما بعث الله محمدًا صلى الله عليه وسلم دُحِروا بالنجوم، فقالت العرب حين لم يخبرهم الجن بذلك: هلك مَن في السماء. فجعل صاحب الإبل ينحر كل يوم بعيرًا، وصاحب البقر ينحر كل يوم بقرة، وصاحب الغنم شاة، حتى أسرعوا في أموالهم، فقالت ثقيف -وكانت أعقل العرب-: أيها الناس، أمسِكوا عليكم أموالكم؛ فإنه لم يمت مَن في السماء، وإنّ هذا ليس بانتشار، ألستم ترون معالمكم مِن النجوم كما هي، والشمس والقمر والليل والنهار؟! قال: فقال إبليس: لقد حدث اليومَ في الأرض حدث، فائتوني مِن تربة كل أرض. فأَتَوه بها، فجعل يشمها، فلما شمَّ تربة مكة قال: مِن هاهنا جاء الحدث. فنقبوا، فإذا رسول الله صلى الله عليه وسلم قد بُعِث."}, "63472": {"num": 63472, "aya": 23, "qail": "مسروق بن الأجدع الهمداني", "tabaqa": "تابعي", "bab": "", "text": "عن مسروق بن الأجدع الهمداني -من طريق أبي الضحى- قال: إذا تكلم اللهُ بالوحي سمع أهلُ السماوات صلصلةً كصلصة الحديد على الصفوان، فيفزعون، فيخرّون سُجّدًا، ويظنون أنه من أمر الساعة، فإذا رُفِّه عن قلوبهم نادوا: {ماذا قالَ رَبُّكُمْ قالُوا الحَقَّ وهُوَ العَلِيُّ الكَبِيرُ}."}, "63473": {"num": 63473, "aya": 23, "qail": "مسروق بن الأجدع الهمداني", "tabaqa": "تابعي", "bab": "", "text": "عن مسروق بن الأجدع الهمداني -من طريق عامر- قال: {حَتّى إذا فُزِّعَ عَن قُلُوبِهِمْ قالُوا ماذا قالَ رَبُّكُمْ قالُوا الحَقَّ وهُوَ العَلِيُّ الكَبِيرُ}: إذا حدث عند ذي العرش أمر سمعتِ الملائكة له صوتًا كجرِّ السلسلة على الصفا، قال: فيُغشى عليهم، فإذا فُزِّع عن قلوبهم قالوا: ماذا قال ربكم؟ قال: فيقول من شاء الله: {الحق، وهو العلي الكبير}."}, "63474": {"num": 63474, "aya": 23, "qail": "عبد الله بن شداد بن الهاد", "tabaqa": "تابعي", "bab": "", "text": "عن عبد الله بن شداد بن الهاد -من طريق يزيد بن أبي زياد- في قوله: {حتى إذا فزع عن قلوبهم} قال: إذا قضى الله في السماوات أمرًا كان وقْعُه كالحديد على الصفوان، فلا يبقى مَلَكٌ إلا خرَّ ساجدًا، {حتى إذا فزع عن قلوبهم} ذهب الروع عنهم، قال: {ماذا قال ربكم قالوا الحق وهو العلي الكبير} قضى كذا وكذا. فيأخذها الشيطان، وهي صِدْقٌ، فينزل بها إلى الأرض، فينزل معه سبعين كذبة، قال: فهي صدق، والسبعون كذب."}, "63475": {"num": 63475, "aya": 23, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد [بن جبير]-من طريق جعفر- قال: ينزل الأمرُ مِن عند رب العزة إلى السماء الدنيا، فيسمعون مثل وقع الحديد على الصفا، فيفزع أهل السماء الدنيا، حتى يستبين لهم الأمر الذي نزل فيه، فيقول بعضهم لبعض: ماذا قال ربُّكم؟ فيقولون: قال الحق، وهو العلي الكبير. فذلك قوله: {حَتّى إذا فُزِّعَ عَنْ قُلُوبِهِمْ} الآية."}, "63477": {"num": 63477, "aya": 23, "qail": "عبد الله بن القاسم", "tabaqa": "تابعي", "bab": "", "text": "عن عبد الله بن القاسم -من طريق قرة- في قوله: {حَتّى إذا فُزِّعَ عَنْ قُلُوبِهِمْ} الآية، قال: الوحي ينزل من السماء، فإذا قضاه، {قالُوا ماذا قالَ رَبُّكُمْ قالُوا الحَقَّ وهُوَ العَلِيُّ الكَبِيرُ}."}, "63478": {"num": 63478, "aya": 23, "qail": "عبد الله بن القاسم", "tabaqa": "تابعي", "bab": "", "text": "عن عبد الله بن القاسم -من طريق قرة بن خالد- أنّه كان يقرؤها: {حَتّى إذا فُزِّعَ عَنْ قُلُوبِهِمْ قالُوا ماذا قالَ رَبُّكُمْ قالُوا الحَقَّ وهُوَ العَلِيُّ الكَبِيرُ}: إن أهل السموات لم يسمعوا الوحي فيما بين عيسى إلى أن بعث الله محمدًا، فلما بعث الله جبريل بالوحي إلى محمد سمع أهل السموات صوتَ الوحي مثل جرِّ السلاسل على الصخور أو الصفا، فصعق أهل السموات مخافة أن تكون الساعة، فلمّا فرغ من الوحي وانحدر جبريل جعل كلما مرَّ بأهل سماء فُزِّع عن قلوبهم، فسأل بعضهم بعضًا، فسأل أهل كل سماء الذي فوقهم إذا جُلِّي عن قلوبهم: {ماذا قالَ رَبُّكُمْ}. فيقولون: {الحَقَّ} أي: هو الحق."}, "63479": {"num": 63479, "aya": 23, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {حَتّى إذا فُزِّعَ عَن قُلُوبِهِمْ قالُوا ماذا قالَ رَبُّكُمْ قالُوا الحَقَّ وهُوَ العَلِيُّ الكَبِيرُ}، قال: يوحي الله إلى جبريل، فتفزع الملائكةُ مخافةَ أن يكون بشيء من أمر الساعة، فإذا جُلّي عن قلوبهم وعلموا أنّ ذلك ليس من أمر الساعة قالوا: ماذا قال ربكم؟ قالوا: الحق."}, "63480": {"num": 63480, "aya": 23, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- ="}, "63486": {"num": 63486, "aya": 23, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {حَتّى إذا فُزِّعَ عَنْ قُلُوبِهِمْ} قال: فُزِّع الشيطان عن قلوبهم وفارقهم وأمانيهم، وما كان يضلهم {قالُوا ماذا قالَ رَبُّكُمْ قالُوا الحَقَّ وهُوَ العَلِيُّ الكَبِيرُ} قال: وهذا في بني آدم، وهذا عند الموت، أقرُّوا به حين لم ينفعهم الإقرار."}}, "n_athar": {"0": 9, "1": 5, "2": 3, "3": 9, "4": 3, "5": 12, "6": 6, "7": 4, "8": 7, "9": 10, "10": 21, "11": 17, "12": 31, "13": 71, "14": 31, "15": 24, "16": 51, "17": 8, "18": 35, "19": 30, "20": 14, "21": 6, "22": 4, "23": 57, "24": 9, "25": 1, "26": 5, "27": 4, "28": 10, "29": 2, "30": 3, "31": 10, "32": 3, "33": 20, "34": 5, "35": 3, "36": 2, "37": 19, "38": 5, "39": 19, "40": 4, "41": 5, "42": 2, "43": 2, "44": 5, "45": 8, "46": 19, "47": 5, "48": 6, "49": 10, "50": 3, "51": 30, "52": 18, "53": 7, "54": 23}, "muh": ["ابن جرير", "ابن عطية", "ابن كثير", "ابن تيمية", "ابن القيم"], "ords": ["الأول", "الثاني", "الثالث", "الرابع", "الخامس", "السادس", "السابع", "الثامن", "التاسع", "العاشر"], "index": "فهرس.html"});